COLLDATA("tadabburar","ar",[[400,"§العنكبوت\nwords\nبِالبُشرَىبِالخَبَرِ السَّارِّ، وَهُوَ: البِشَارَةُ بِإِسحَاقَ -عليه السلام-.\nالغَابِرِينَالبَاقِينَ فِي العَذَابِ.\nوَضَاقَ بِهِم ذَرعًاضَاقَ صَدرُهُ، وَحَزِنَ خَوفًا عَلَيهِم.\nرِجزًاعَذَابًا شَدِيدًا.\nوَلاَ تَعثَوالاَ تُكثِرُوا الفَسَادَ.\nالرَّجفَةُالزَّلزَلَةُ الشَّدِيدَةُ.\ndeeds\nتعرف على أحوال الصالحين المجاورين لك وعلى أخبارهم، ودافع عنهم.\nهوّن على أحد زملائك ما يجد من حزن وضيق صدر.\nقل: \"اللهم لا تؤاخذنا بما فعل السفهاء منا\".\nguid\nالإيمان والعمل الصالح هما سبب النجاة من العقوبات، والعلاقة الزوجية بدونهما لا تنفع شيئًا.\nتذكُّر اليوم الآخر والخوف منه من أعظم ما يعين على ترك المعاصي.\nمن خطوات الشيطان في إضلال العباد: تزيين الأعمال السيئة؛ فالحذر الحذر من ذلك.\nrefl\nوَلَمَّا جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُوٓاْ إِنَّا مُهۡلِكُوٓاْ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِۖ إِنَّ أَهۡلَهَا كَانُواْ ظَٰلِمِينَ ٣١\nومن لطف الله بإبراهيم أن قدّم له البشرى قبل إعلامه بإهلاك قوم لوط؛ لعلمه تعالى بحلم إبراهيم. ابن عاشور:٢٠/٢٤٢.\nما فائدة تقديم البشرى على الإخبار بإهلاك قوم لوط؟\nإِنَّا مُنزِلُونَ عَلَىٰٓ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ ٣٤\nعن ابن عباس قال: إن قوم لوط كانت فيهم ذنوب غير الفاحشة؛ منها: أنهم يتظالمون فيما بينهم، ويشتم بعضهم بعضًا... وتتشبه الرجال بلباس النساء والنساء بلباس الرجال، ويضربون المكوس على كل عابر، ومع هذا كله كانوا يشركون بالله، وهم أول من ظهر على أيديهم اللوطية والسحاق. القرطبي:١٣/٣٤٢.\nمن خلال هذه الآية: بيّن أسباب هلاك المدن والدول.\nوَلَقَد تَّرَكۡنَا مِنۡهَآ ءَايَةَۢ بَيِّنَةٗ لِّقَوۡمٖ يَعۡقِلُونَ ٣٥\nأي: ولقد أبقينا من فعلتنا التي فعلنا بهم (آية): يقول: عبرة بينة، وَعِظَةٌ واعظة ﴿لِّقَوۡمٍ يَعۡقِلُونَ﴾ عن الله حججه، ويتفكرون في مواعظه. الطبري:٢٠/٣٣.\nما فائدة بقاء آثار القرون الأولى التي أهلكها الله؟\nوَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ٣٦\nأي: لا تكفروا؛ فإنه أصل كل فساد، والعثو والعثي: أشد الفساد. القرطبي:١٦/٣٦١.\nما أعظم الفساد الذي نهى عنه نبي الله شعيب -عليه السلام-؟\nوَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ ٣٨\n﴿وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ﴾ بوسوسته وإغوائه (أعمالهم) القبيحة من الكفر والمعاصي... (مستبصرين) أي: عقلاء؛ يمكنهم التمييز بين الحق والباطل بالاستدلال والنظر، ولكنهم أغفلوا ولم يتدبروا. الألوسي:١٠/٣٦٢.\nما أهم طرق الشيطان لإغواء العقلاء من الناس؟\nوَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ ٣٨\n﴿وَكَانُواْ مُسۡتَبۡصِرِينَ﴾: قيل: معناه لهم بصيرة في كفرهم، وإعجاب به، وقيل: لهم بصيرة في الإيمان، ولكنهم كفروا عنادًا. ابن جزي:٢/١٥٩.\nهل كل كفر سببه الجهل؟\nوَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ ٣٨\nكانوا مستبصرين: قد عرفوا الحق من الباطل بظهور البراهين..، قال الفراء: \"كانوا عقلاء ذوي بصائر، فلم تنفعهم بصائرهم\". القرطبي:١٦/٣٦٢.\nهل ينتفع الإنسان بعقله إذا عصى ربه تعالى؟"],[401,"§العنكبوت\nwords\nوَمَا كَانُوا سَابِقِينَفَائِتِينَ مِن عَذَابِ اللهِ.\nأَخَذنَا بِذَنبِهِأَخَذنَا المَذكُورِينَ بِعَذَابِنَا بِسَبَبِ ذُنُوبِهِم.\nحَاصِبًاحِجَارَةً مِن طِينٍ مَنضُودٍ.\nأَوهَنَأَضعَفَ.\nوَمَا يَعقِلُهَايَتَدَبَّرُهَا، وَيَفهَمُهَا.\ndeeds\nاستعذ بالله من الكبر؛ فهو من أسباب رد الحق.\nاتل سورة من سور القرآن، فهو الوحي الذي تستنير به القلوب، وتصلح به أمور الدنيا والدين.\nأدّ الصلوات الخمس في أحسن حال حتى تكون مانعة لك من فحش أعمال القلوب؛ كالمحبة والخوف، ومانعة من منكرات الجوارح.\nguid\nمن عدل الله -تبارك وتعالى- أنه لا يعذّب أحدًا إلا بما كسب.\nتذكر أن الله تعالى لا يظلم الناس شيئًا، وإنَّما يظلم العبد نفسه بالذنوب.\nفضل العلم، وأنه من أسباب الانتفاع بما يضرب الله للعباد من أمثال.\nrefl\nمَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُواْ يَعۡلَمُونَ ٤١\nقال الفراء: \"هو مثل ضربه الله سبحانه لمن اتخذ من دونه آلهة لا تنفعه ولا تضره؛ كما أن بيت العنكبوت لا يقيها حرًا ولا بردًا\"...أي: لو علموا أن عبادة الأوثان كاتخاذ بيت العنكبوت التي لا تغني عنهم شيئًا، وأن هذا مثلهم لما عبدوها. القرطبي:١٦/٣٦٣.\nبيّن وجه الشبه بين بيت العنكبوت والقبور والأضرحة التي تُعبد من دون الله.\nمَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُواْ يَعۡلَمُونَ ٤١\nفالمشركون أشبهوا العنكبوت في الغرور بما أعدوه، وأولياؤهم أشبهوا بيت العنكبوت في عدم الغَنَاء عمن اتخذوها وقت الحاجة إليها وتزول بأقل تحريك. ابن عاشور:٢٠/٢٥٢.\nما وجه شبه المشركين وأوليائهم بالعنكبوت وبيتها؟\nوَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا يَعۡقِلُهَآ إِلَّا ٱلۡعَٰلِمُونَ ٤٣\nلا يفهم مغزاها إلا الذين كمُلت عقولهم؛ فكانوا علماء غير سفهاء الأحلام. وفي هذا تعريض بأن الذين لم ينتفعوا بها جهلاء العقول؛ فما بالك بالذين اعتاضوا عن التدبر في دلالتها باتخاذها هُزءًا وسخرية. ابن عاشور:٢٠/٢٥٦.\nما خطورة عدم تدبر أمثال القرآن؟\nوَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا يَعۡقِلُهَآ إِلَّا ٱلۡعَٰلِمُونَ ٤٣\nوالسبب في ذلك أن الأمثال التي يضربها الله في القرآن إنَّما هي للأمور الكبار، والمطالب العالية، والمسائل الجليلة؛ فأهل العلم يعرفون أنها أهم من غيرها لاعتناء الله بها، وحثه عباده على تعقلها وتدبرها، فيبذلون جهدهم في معرفتها. السعدي:٦٣١.\nلماذا خُصَّت معرفة الأمثال بالعالمين؟\nٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ\nوالإكثار في تلاوته يزيد بصيرة في أمره، ويفتح كنوز الدقائق من علمه، وهو أكرم من أن ينيل قارئه فائده، وأجلّ من أن يعطي قياد فوائده ويرفع الحجاب عن جواهره وفرائده في أول مرة، بل كلما ردده القارئ بالتدبر حباه بكنز من أسراره، ومهما زاد زاده من لوامع أنواره، إلى أن يقطع بأن عجائبه لا تُعد، وغرائبه لا تُحد. البقاعي:١٤/ ٤٤٧.\nمتى يستفيد المسلم من تلاوة القرآن؟\nوَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ\nروي عن بعض السلف أنه كان إذا قام إلى الصلاة ارتعد واصفر لونه، فكُلِّم في ذلك، فقال: \"إني واقف بين يدي الله تعالى، وحُقّ لي هذا مع ملوك الدنيا؛ فكيف مع ملك الملوك؟!\"؛ فهذه صلاة تنهى ولا بد عن الفحشاء والمنكر. ومن كانت صلاته دائرة حول الإجزاء؛ لا خشوع فيها، ولا تذكُّر، ولا فضائل -كصلاتنا وليتها تجزي-، فتلك تترك صاحبها من منزلته حيث كان. القرطبي:١٦/٣٦٧.\nما نوع الصلاة التي تنهى صاحبها عن الفحشاء والمنكر؟\nوَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ\nإذا كان المصلي خاشعًا في صلاته، متذكرًا لعظمة من وقف بين يديه؛ حمله ذلك على التوبة من الفحشاء والمنكر؛ فكأن الصلاة ناهية عن ذلك. ابن جزي:٢/١٦٠.\nكيف تكون الصلاة ناهية عن الفحشاء والمنكر؟"],[402,"§العنكبوت\nwords\nظَلَمُوا مِنهُمعَانَدُوا الحَقَّ، وَأَعلَنُوا الحَربَ.\nمُسلِمُونَخَاضِعُونَ مُتَذَلِّلُونَ بِالطَّاعَةِ.\nوَمِن هَؤُلاَءِالعَرَبِ مِن قُرَيشٍ.\nلَولاَهَلاَّ.\nآيَاتٌحُجَجٌ وَبَرَاهِينُ نُشَاهِدُهَا؛ كَنَاقَةِ صَالِحٍ -عليه السلام-.\ndeeds\nاحفظ اليوم آيات لم تكن تحفظها من قبل.\nتدرب على الحوار؛ فهو من سنن الأنبياء؛ اختر زميلًا وحاوره بهدوء وحكمة، واحرص على العدل والانصاف في كلامك.\nادع الله تعالى أن يجعلك مستسلمًا لأمره وشرعه.\nguid\nالعالم من عرف العبادة الصحيحة ولو كان لا يقرأ ولا يكتب.\nالقرآن بلغ الغاية في الفصاحة، مع أن المرسل به نبينا -صلى الله عليه وسلم- أمي لا يقرأ ولا يكتب.\nفضلُ الله سبحانه على هذه الأمة؛ إذ أنزل إليهم خير كتاب على أفضل رسول.\nrefl\n۞وَلَا تُجَٰدِلُوٓاْ أَهۡلَ ٱلۡكِتَٰبِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡۖ وَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ٤٦\nووجه الوصاية بالحسنى في مجادلة أهل الكتاب: أن أهل الكتاب مؤمنون بالله غير مشركين به؛ فهم متأهّلون لقبول الحجة، غير مظنون بهم المكابرة، ولأن آداب دينهم وكتابهم أكسبتهم معرفة طريق المجادلة؛ فينبغي الاقتصار في مجادلتهم على بيان الحجة دون إغلاظ حذرًا من تنفيرهم. ابن عاشور:٢١/٦.\nما وجه الوصاية بالحسنى في مجادلة أهل الكتاب؟\nوَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ\nولا تكن مناظرتكم إياهم على وجه يحصل به القدح في شيء من الكتب الإلهية، أو بأحد من الرسل؛ كما يفعله الجاهل عند مناظرة الخصوم؛ يقدح بجميع ما معهم من حق وباطل؛ فهذا ظلم وخروج عن الواجب وآداب النظر؛ فإن الواجب أن يرد ما مع الخصم من الباطل، ويقبل ما معه من الحق، ولا يرد الحق لأجل قوله ولو كان كافرًا. السعدي:٦٣٢.\nالجدال مع الكافر مبني على العدل والحكمة، وضح ذلك من خلال الآية.\nوَكَذَٰلِكَ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَۚ فَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَٰٓؤُلَآءِ مَن يُؤۡمِنُ بِهِۦۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلۡكَٰفِرُونَ ٤٧\nوجيء بصيغة المضارع للدلالة على أنه سيقع في المستقبل، أو للدلالة على تجدد إيمان هذا الفريق به؛ أي إيمان من آمن منهم مستمرّ يزداد عدد المؤمنين يومًا فيومًا. ابن عاشور:٢١/٩.\nلماذا جيء بالفعل (يؤمنون) في الآية بصيغة المضارع؟\nوَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلۡكَٰفِرُونَ ٤٧\nالذين دأبهم الجحود للحق والعناد له، وهذا حصر لمن كفر به؛ أنه لا يكون من أحد قصده متابعة الحق، وإلا فكل من له قصد صحيح فإنه لا بد أن يؤمن به؛ لما اشتمل عليه من البينات لكل من له عقل، أو ألقى السمع وهو شهيد. السعدي:٦٣٣.\nهل يكفر بهذا القرآن من له قصدٌ حَسَنٌ؟\nبَلۡ هُوَ ءَايَٰتُۢ بَيِّنَٰتٞ فِي صُدُورِ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ ٤٩\nقال الحسن: \"أعطيت هذه الأمة الحفظ، وكان من قبلها لا يقرءون كتابهم إلا نظرًا، فإذا أطبقوه لم يحفظوا ما فيه، إلا النبيون\". القرطبي:١٦/٣٧٦.\nلحفظ القرآن الكريم فضل عظيم، بينه.\nأَوَ لَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ إِنَّ فِي ذَٰلِكَ لَرَحۡمَةٗ وَذِكۡرَىٰ لِقَوۡمٖ يُؤۡمِنُونَ ٥١\nالمعنى: كيف يطلبون آية والقرآن الكريم أعظم الآيات، وأوضحها دلالة على صحة النبوة؛ فهلا اكتفوا به عن طلب الآيات. ابن جزي:٢/١٦١.\nكيف يكون نزول القرآن ردًا على من زعم أن القرآن جاء به النبي ؟\nقُلۡ كَفَىٰ بِٱللَّهِ بَيۡنِي وَبَيۡنَكُمۡ شَهِيدٗاۖ\nيعلم ما أقول لكم من إخباري عنه بأنه أرسلني، فلو كنت كاذبًا عليه لانتقم مني. ابن كثير: ٣/٤٠٤\nكيف تكون شهادة الله على صدق نبوة محمد -صلى الله عليه وسلم- ؟"],[403,"§العنكبوت\nwords\nأَجَلٌ مُسَمّىًوَقتُ عَذَابِهِمُ المُقَدَّرُ عِندَ اللهِ.\nيَغشَاهُمُيُحِيطُ بِهِم وَيَعلُوهُم.\nوَكَأَيِّن مِنوَكَم مِن؟\nفَأَنَّى يُؤفَكُونَفَكَيفَ يُصرَفُونَ عَنِ الإِيمَانِ!\nيَبسُطُيُوَسِّعُ.\nوَيَقدِرُيُضَيِّقُ.\ndeeds\nسَلِ الله أن يرزقك الصبر، ويعينك عليه.\nحدد أوقات قدرتك على العمل في يومك وأسبوعك ثم اقسمها بين العمل للدنيا وللآخرة متيقنًا أن رزقك على الله لا على جهدك.\nتأمل النمل والطير كيف يسوق الله تعالى إليها رزقها، ثم ادع الله أن يرزقك رزقًا حلالًا طيبًا، مباركًا فيه.\nguid\nاحذر أن يأتيك أجلك وأنت على معصية الله.\nلا عذر لأحد في ترك عبادة الله وتوحيده؛ لأنه إن منع منها في بلد وجب عليه أن يهاجر إلى بلد آخر.\nلا تحمل هم الرزق؛ فإن الله قد كفاك إياه.\nrefl\nيَوۡمَ يَغۡشَىٰهُمُ ٱلۡعَذَابُ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ\nفالنار تغشاهم من سائر جهاتهم، وهذا أبلغ في العذاب الحسي. ابن كثير:٣/٤٠٤.\nلماذا وصف العذاب بأنه يغشاهم من فوقهم ومن تحتهم؟\nوَيَقُولُ ذُوقُواْ مَا كُنتُمۡ تَعۡمَلُونَ ٥٥\nوهذا عذاب معنوي على النفوس. ابن كثير:٣/٤٠٤.\nلماذا يقال لهم في جهنم هذه المقولة؟\nيَٰعِبَادِيَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ أَرۡضِي وَٰسِعَةٞ فَإِيَّٰيَ فَٱعۡبُدُونِ ٥٦\nفإذا تعذرت عليكم عبادة ربكم في أرض فارتحلوا منها إلى أرض أخرى؛ حيث كانت العبادة لله وحده؛ فأماكن العبادة ومواضعها واسعة والمعبود واحد. السعدي:٦٣٤.\nما المراد من إخبار المؤمنين بأن أرض الله واسعة؟\nيَٰعِبَادِيَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ أَرۡضِي وَٰسِعَةٞ فَإِيَّٰيَ فَٱعۡبُدُونِ ٥٦ كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَيۡنَا تُرۡجَعُونَ ٥٧\nوإنَّما ذكره هاهنا تحقيرًا لأمر الدنيا ومخاوفها؛ كأن بعض المؤمنين نظر في عاقبة تلحقه في خروجه من وطنه من مكة؛ أنه يموت أو يجوع أو نحو هذا، فحقَّر الله شأن الدنيا. أي: أنتم لا محالة ميتون، ومحشورون إلينا، فالبدار إلى طاعة الله، والهجرة إليه وإلى ما يمتثل. القرطبي:١٦/٣٨٢.\nبما ترد على من يقول: كيف أعيش إن خرجت من أرض المعاصي ورزقي فيها؟\nوَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفٗا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ ٥٨\nوقصد منها أيضًا تهوين ما يلاقيه المؤمنون من الأذى في الله -ولو بلغ إلى الموت- بالنسبة لما يترقبهم من فضل الله وثوابه الخالد. ابن عاشور:٢١/٢٣.\nوضح في ضوء الآية هوان ما يلاقيه المؤمن من أذى مقابل ما ينتظره من ثواب.\nوَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ٦٠\nأي: كم من دابة ضعيفة لا تقدر على حمل رزقها، ولكن الله يرزقها مع ضعفها. والقصد بالآية: تقوية لقلوب المؤمنين؛ إذا خافوا الفقر والجوع في الهجرة إلى بلاد الناس، أي: كما يرزق الله الحيوانات الضعيفة كذلك يرزقكم إذا هاجرتم من بلدكم. ابن جزي:٢/١٦٢.\nفي هذه الآية تقوية لقلوب المؤمنين، وتزكية للنفوس، وضح ذلك.\nوَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ٦٠\n﴿ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ﴾: يسوي بين الحريص والمتوكل في رزقه، وبين الراغب والقانع، وبين الحيول والعاجز؛ حتى لا يغتر الجَلْد أنه مرزوق بجلده، ولا يتصور العاجز أنه ممنوع بعجزه. القرطبي:١٦/٣٨٦.\nهل يزاد في رزق الحريص على الرزق لحرصه؟"],[404,"§العنكبوت ، الروم\nwords\nالحَيَوَانُالحَيَاةُ الحَقِيقِيَّةُ الكَامِلَةُ الدَّائِمَةُ.\nالفُلكِالسُّفُنِ.\nوَيُتَخَطَّفُ النَّاسُيُستَلَبُونَ بِسُرعَةٍ قَتلًا وَأَسرًا.\nمَثوىًمَسكَنٌ وَمُستَقَرٌّ.\nغُلِبَتِ الرُّومُهَزَمَت فَارِسُ الرُّومَ.\nأَدنَى الأَرضِأَقرَبِ أَرضِ الشَّامِ إِلَى فَارِسَ.\nبِضعِ سِنِينَالبِضعُ: مُدَّةٌ لاَ تَزِيدُ عَلَى عَشرِ سَنَوَاتٍ، وَلاَ تَنقُصُ عَن ثَلاَثٍ.\ndeeds\nاحمد الله تعالى على نعمة الأمن والأمان.\nاعمل عملًا يحبّه الله، وإن كنت تجد فيه مشقة.\nأنفق نفقة في سبيل الله.\nguid\nنعمة الأمن في الديار والأوطان نعمة عظيمة، والمحافظة عليها تكون بالأعمال الصالحة وإقامة شعائر الله.\nبشرى الله لمن جاهد المشركين، وجاهد نفسه بالهداية إلى سبيله.\nاعلم أن النصر ليس بمقدار العدد والعُدة، وإنَّما هو بيد الله تعالى يؤتيه من يشاء.\nrefl\nوَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ\nفجيء باسم الإِشارة لإفادة تحقيرها. ابن عاشور:٢١/٣١.\nما فائدة اسم الإشارة (هذه) في الآية الكريمة؟\nوَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ٦٤\nأي: شيء يلهى به ويلعب، أي: ليس ما أعطاه الله الأغنياء من الدنيا إلا وهو يضمحل ويزول؛ كاللعب الذي لا حقيقة له ولا ثبات. قال بعضهم: \"الدنيا إن بقيت لك لم تبق لها\". القرطبي:١٦/٣٨٧.\nبيّن حقيقة الدنيا كما ذكرها خالقها -سبحانه وتعالى-.\nفَإِذَا رَكِبُواْ فِي ٱلۡفُلۡكِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ يُشۡرِكُونَ ٦٥\nلأن أسفارهم في البر كانوا لا يعتريهم فيها خوفٌ يعم جميع السفر؛ لأنهم كانوا يسافرون قوافلَ، معهم سلاحهم، ويمرون بسبل يألفونها؛ فلا يعترضهم خوف عام، فأما سفرهم في البحر؛ فإنهم يَفرَقون من هوله، ولا يدفعه عنهم وفرة عدد، ولا قوة عُدد؛ فهم يضرعون إلى الله بطلب النجاة، ولعلهم لا يدعون أصنامهم حينئذ. ابن عاشور:٢١/٣٢.\nلماذا خص السفر في البحر بالخوف؟\nأَوَ لَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ يَكۡفُرُونَ ٦٧\nأي: جعلت لهم حرمًا آمنًا؛ أمنوا فيه من السبي والغارة والقتل، وخلصتهم في البر كما خلصتهم في البحر؛ فصاروا يشركون في البر، ولا يشركون في البحر. فهذا تعجب من تناقض أحوالهم. القرطبي:١٦/٣٨٩.\nبيّن تناقض المشركين من خلال الآية.\nوَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ ٦٩\nقال أبو سليمان الداراني: \"ليس الجهاد في الآية قتال الكفار فقط، بل هو نصر الدين، والرد على المبطلين، وقمع الظالمين، وعِظَمُه: الأمر بالمعروف، والنهي عن المنكر، ومنه مجاهدة النفوس في طاعة الله؛ وهو الجهاد الأكبر\". القرطبي:١٦/٣٩٠.\nهل هذا الجزاء العظيم بالهداية هو خاص بقتال الكفار فقط؟\nلِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ\nفليس الغلبة والنصر لمجرد وجود الأسباب، وإنَّما هي لا بد أن يقترن بها القضاء والقدر. السعدي:٦٣٦.\nما وجه إدخال هذه الجملة في قصة فارس والروم؟\nوَيَوۡمَئِذٖ يَفۡرَحُ ٱلۡمُؤۡمِنُونَ ٤\nفرِح المؤمنون بنصر الروم على الفرس؛ لأن الروم أهل كتاب؛ فهم أقرب إلى الإسلام، كذلك فرح الكفار من قريش بنصر الفرس على الروم؛ لأن الفرس ليسوا بأهل كتاب؛ فهم أقرب إلى كفار قريش. ابن جزي:٢/١٦٤.\nلمَ فرح المؤمنون بانتصار الروم مع كونهم كفارًا؟"],[405,"§الروم\nwords\nوَأَجَلٍ مُسَمّىًوَقتٍ مُقَدَّرٍ تَنتَهِي إِلَيهِ.\nوَأَثَارُواحَرَثُوا وَزَرَعُوا.\nالسُّوأَىالعُقُوبَةُ المُتَنَاهِيَةُ فِي السُّوءِ.\nيُبلِسُيَيْأَسُ مِنَ النَّجَاةِ مِنَ العَذَابِ.\nيُحبَرُونَيُكرَمُونَ، وَيُنَعَّمُونَ.\ndeeds\nاستمع إلى محاضرة في وصف الجنة والنار.\nاختر واحدة من جوارحك، ثم تأمل كيف خلقها الله، واكتب ثلاث فوائد استفدتها من تأملك.\nسل الله تعالى أن يرزقك شفاعة النبي -صلى الله عليه وسلم- وأن يوفقك لحسن اتباعه.\nguid\nاربط ما تتعلمه من علوم دنيوية بعظمة الله وقدرته حتى تنتفع به.\nالتفكر من أجلّ العبادات، ومن رزق التدبر فقد رزق يقظة القلب؛ لأنه يجعله دائم الصلة بالله.\nتقرير عقيدة أن لا شفاعة لمشرك يوم القيامة.\nrefl\nوَعۡدَ ٱللَّهِۖ لَا يُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٦\nوإضافة الوعد إلى الله تلويح بأنه وعد محقق الإيفاء؛ لأن وعد الصادق القادر الغني لا موجب لإخلافه. ابن عاشور:٢١/٤٨.\nما فائدة إضافة الوعد إلى الله تعالى؟\nيَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ غَٰفِلُونَ ٧\nومن العجب أن هذا القسم من الناس قد بلغت بكثير منهم الفطنة والذكاء في ظاهر الدنيا إلى أمر يحير العقول، ويدهش الألباب، وأظهروا من العجائب الذرية والكهربائية، والمراكب البرية والبحرية والهوائية ما فاقوا به وبرزوا... وهم مع ذلك أبلد الناس في أمر دينهم، وأشدهم غفلة عن آخرتهم، وأقلهم معرفة بالعواقب، قد رآهم أهل البصائر النافذة في جهلهم يتخبطون، وفي ضلالهم يعمهون، وفي باطلهم يترددون... فعرفوا أن الأمر لله، والحكم له في عباده، وإن هو إلا توفيقه وخذلانه؛ فخافوا ربهم، وسألوه أن يتم لهم ما وهبهم من نور العقول والإيمان؛ حتى يصلوا إليه، ويحلوا بساحته. السعدي:٦٣٧.\nكيف نوازن بين علم الدنيا وعلم الآخرة؟\nيَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ غَٰفِلُونَ ٧\nقال الحسن: \"إن أحدهم لينقر الدرهم بطرف ظفره فيذكر وزنه ولا يخطئ، وهو لا يحسن يصلي\" انتهى. وأمثال هذا لهم كثير، وهو وإن كان عند أهل الدنيا عظيمًا فهو عند الله حقير؛ فلذلك حقره لأنهم ما زادوا فيه على أن ساووا البهائم في إدراكها ما ينفعها؛ فتستجلبه بضروب من الحيل، وما يضرها؛ فتدفعه بأنواع من الخداع. البقاعي:١٥/ ٤٤- ٤٥.\nما العلم النافع في الآخرة؟\nيَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ غَٰفِلُونَ ٧\nيعني: أمر معايشهم؛ كيف يكتسبون ويتجرون، ومتى يغرسون ويزرعون ويحصدون، وكيف يبنون ويعيشون، ﴿وَهُمۡ عَنِ ٱلۡأٓخِرَةِ هُمۡ غَٰفِلُونَ﴾، ساهون عنها جاهلون، لا يتفكرون فيها ولا يعملون لها. البغوي:٣/٤٨٨.\nمتى يذم أهل العلوم الدنيوية؟\nفَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ٩\n(يظلمون) أي: يجددون الظلم لها بإيقاع الضر موقع جلب النفع؛ لأنهم لا يعتبرون بعقولهم التي ركبناها فيهم ليستضيؤوا بها فيعلموا الحق من الباطل، ولا يقبلون من الهداة إذا كشفوا لهم ما عليها من الغطاء، ولا يرجعون عن الغي إذا اضطروهم بالآيات الباهرات، بل ينتقلون من الغفلة إلى العناد. البقاعي:١٥/٥٢.\nكيف يكون تعطيل العقل ظلمًا؟\nوَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ٩\nعُبِّـرَ عن ظُلمِهِم أَنفُسَهُم بصيغة المضَارِع للدلالة على استمرار ظلمهم وتكرره، وأن الله أمهلهم فلم يقلعوا حتى أخذهم. ابن عاشور:٢١/٥٨.\nما فائدة صيغة المضارع في حال التعبير عن ظلم المشركين أنفسهم؟\nفَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَهُمۡ فِي رَوۡضَةٖ يُحۡبَرُونَ ١٥\n(يحبرون): يتبين عليهم أثر النعيم، وقال يحيى بن أبي كثير -﴿فِي رَوۡضَةٍ يُحۡبَرُونَ﴾- قال: \"السماع في الجنة\"، وقاله الأوزاعي؛ قال: \"إذا أخذ أهل الجنة في السماع لم تبق شجرة في الجنة إلا رددت الغناء بالتسبيح والتقديس\". القرطبي:١٦/٤٠٦.\nمن خلال الآية بيِّن كيف يكون حال المؤمن في الجنة."],[406,"§الروم\nwords\nمُحضَرُونَمُقِيمُونَ.\nتُظهِرُونَتَدخُلُونَ وَقتَ الظَّهِيرَةِ.\nلِلعَالِمِينَجَمعُ عَالِم، وَهُم ذَوُو العِلمِ وَالبَصِيرَةِ.\nوَابتِغَاؤُكُم مِن فَضلِهِطَلَبُكُم لِلرِّزقِ فِي النَّهَارِ.\nخَوفًا وَطَمَعًاتَخَافُونَ مِنَ الصَّوَاعِقِ، وَتَطمَعُونَ فِي الغَيثِ.\ndeeds\nقل: \"سبحان الله وبحمده\" مائة مرة في المساء، أو الصباح، أو العشي، أو الظهر، أو فيها جميعًا.\nبادر بحفظ ما لم تحفظه من أذكار الصباح والمساء.\nساعد والديك في تقديم كل منهما هدية للآخر؛ توددًا وتحببًا.\nguid\nمن أصول التربية: الثواب والعقاب.\nذكر الله يكون طوال اليوم.\nسبحان من يدرك الأصوات على اختلاف اللغات، فيلبي الحاجات ويتجاوز عن الزلات.\nrefl\nيُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ\nيذكُر فيها خلقَه الأشياء وأَضدادها، ليدلَّ خَلقُه علَى كَمالِ قُدرته، فَمن ذلكَ إِخراج النبات من الحَبِّ والحَبِّ من النبات، والبَيضِ من الدَّجَاجِ والدَّجَاجِ من البَيضِ، والإنسانِ من النُّطفَةِ والنُّطفَةِ من الإِنسانِ، والمؤمِنِ من الكَافرِ والكَافرِ من المؤمن. ابن كثير:٦/٢٧٧.\nما الذي يستفاد من إخبار الله عن خلقه الأشياء وأضدادها؟\nوَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ٢١\nجعل بين الزوجين المودة والرحمة؛ فهما يتوادّان ويتراحمان، وما شيء أحب إلى أحدهما من الآخر، من غير رحم بينهما. ﴿إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍ لِّقَوۡمٍ يَتَفَكَّرُونَ﴾ في عظمة اللّه وقدرته. البغوي:٣/٤٩١.\nبيّن عظيم إنعام الله تعالى بجعل المودة والرحمة بين الزوجين.\nوَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ\nومن عنايته بعباده ورحمته بهم أن قدّر ذلك الاختلاف -اختلاف الألسنة والألوان- لئلَّا يقع التشابه؛ فيحصل الاضطراب، ويفوت كثير من المقاصد. السعدي:٦٣٩.\nفي اختلاف الألسنة والألوان بيان لرحمة الله عند المتفكرين، ما وجه ذلك؟\nوَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ\nجميع أهل الأرض، بل أهل الدنيا منذ خلق الله آدم إلى قيام الساعة؛ كل له عينان وحاجبان وأنف وجبين وفم وخدان، وليس يشبه واحد منهم الآخر، بل لا بد أن يفارقه بشيء من السمت أو الهيئة أو الكلام -ظاهرًا كان أو خفيًّا- يظهر عند التأمل؛ كل وجه منهم أسلوب بذاته، وهيئته لا تشبه أخرى. ابن كثير:٦/٢٧٩.\nإذا تأملت أنواع البشر في خلقتهم، فماذا تستفيد من ذلك؟\nوَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ\n﴿وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ﴾: اللسان في الفم، وفيه اختلاف اللغات؛ من العربية، والعجمية، والتركية، والرومية. واختلاف الألوان في الصور؛ من البياض، والسواد، والحمرة؛ فلا تكاد ترى أحدًا إلا وأنت تفرق بينه وبين الآخر، وليس هذه الأشياء من فعل النطفة، ولا من فعل الأبوين؛ فلا بد من فاعل، فعلم أن الفاعل هو الله تعالى؛ فهذا من أدل دليل على المدبر البارئ. القرطبي:١٦/٤١٣.\nعلى ماذا يدل اختلاف الألسنة والألوان؟\nوَمِنۡ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ وَٱبۡتِغَآؤُكُم مِّن فَضۡلِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ ٢٣\nوفي اقتران الفضل بالابتغاء إشارة إلى أن العبد ينبغي أن لا يرى الرزق من نفسه وبحذقه، بل يرى كل ذلك من فضل ربه -جلّ وعلا-. الألوسي:١١/٣٣.\nما الذي يفيده اقتران الفضل بالابتغاء في قوله: ﴿وَٱبۡتِغَآؤُكُم مِّن فَضۡلِهِۦٓۚ﴾؟\nوَمِنۡ ءَايَٰتِهِۦ يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءٗ فَيُحۡيِۦ بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ٢٤\nونيط الانتفاع بهذه الآيات بأصحاب صفة العقل؛ لأن العقل المستقيم غير المشوب بعاهة العناد والمكابرة كافٍ في فهم ما في تلك المذكورات من الدلائل والحكم. ابن عاشور:٢١/٧٩.\nلماذا جعل الانتفاع في الآية الكريمة خاصًا بأهل العقول؟"],[407,"§الروم\nwords\nفِطرَةَ اللهِالزَمُوا دِينَ اللهِ، وَهُوَ الإِسلاَمُ.\nفَطَرَ النَّاسَ عَلَيهَاجَبَلَهُم وَطَبَعَهُم عَلَيهَا.\nالقَيِّمِالمُستَقِيمِ المُوصِلِ إِلَى رِضَا اللهِ.\nفَرَّقُوا دِينَهُمبَدَّلُوا دِينَهُم وَغَيَّرُوهُ فَأَخَذُوا بَعضًا وَتَرَكُوا بَعضًا.\nشِيَعًافِرَقًا وَأَحزَابًا.\ndeeds\nاستفتح صلواتك بهذا الدعاء الثابت: «وجهت وجهي للذي فطر السماوات والأرض حنيفًا وما أنا من المشركين» [رواه مسلم].\nأقم الصلاة مع الجماعة بخشوع وطمأنينة؛ لتحقق الإيمان.\nاستعذ بالله، وحذّر من حولك من تفريق جماعة المؤمنين.\nguid\nالكون من حولك قانت، خاضع لله، فلا تكن من المعرضين الغافلين.\nكثيرًا ما يبين الله في كتابه أن سبب إعراض المعرضين هو اتباع الهوى.\nمن عادة المشركين الافتراق؛ فاحذر من مشابهتهم.\nrefl\nوَهُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٢٧\nومن جملة المثَل الأعلى: عزته وحكمته تعالى؛ فخُصّا بالذكر هنا لأنهما الصفتان اللتان تظهر آثارهما في الغرض المتحدث عنه؛ وهو: بدء الخلق وإعادته؛ فالعزة تقتضي الغِنى المطلق؛ فهي تقتضي تمام القدرة، والحكمة تقتضي عموم العلم. ابن عاشور:٢١/٨٤.\nلماذا خصت صفتا ﴿ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾ بالذكر في الآية الكريمة؟\nوَهُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِۚ\n(وهو) أي: الإعادة للخلق بعد موتهم. ﴿أَهۡوَنُ عَلَيۡهِۚ﴾ من ابتداء خلقهم، وهذا بالنسبة إلى الأذهان والعقول؛ فإذا كان قادرًا على الابتداء الذي تُقِرُّون به؛ كانت قدرته على الإعادة أهون وأولى. السعدي:٦٤٠.\nأسلوب الرد العقلي مستخدم في القرآن، وضحه من خلال هذه الآية.\nكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡقِلُونَ ٢٨\nوالقوم الذين يعقلون هم المتنزهون عن المكابرة والإعراض، والطالبون للحق والحقائق لوفرة عقولهم؛ فيزداد المؤمنون يقينًا، ويؤمن الغافلون والذين تروج عليهم ضلالات المشركين ثم تنكشف عنهم بمثل هذه الدلائل البينة... وفي هذا تعريض بالمتصلّبين في شركهم بأنهم ليسوا من أهل العقول، وليسوا ممن ينتفعون. ابن عاشور:٢١/٨٧.\nبيِّن من خلال الوقفة أهم أوصاف العقلاء.\nكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡقِلُونَ ٢٨\nوأما من لا يعقل؛ فلو فُصِّلت له الآيات، وبُيِّنت له البينات، لم يكن له عقل يبصر به ما تبين، ولا لُبٌّ يعقل به ما توضح، فأهل العقول والألباب هم الذين يساق إليهم الكلام، ويوجه الخطاب. السعدي:٦٤٠.\nلماذا خُصَّ العقلاء بالخطاب؟\nفَأَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٣٠\nوصف الإسلام بأنه فطرة الله معناه: أن أصل الاعتقاد فيه جار على مقتضى الفطرة العقلية، وأمَّا تشريعاته وتفاريعه فهي: إما أمور فطرية أيضًا؛ أي: جارية على وفق ما يدركه العقل ويشهد به، وإما أن تكون لصلاحه مما لا ينافِي فطرته. ابن عاشور:٢١/٩١.\nما معنى وصف الإسلام بالفطرة؟\n۞مُنِيبِينَ إِلَيۡهِ وَٱتَّقُوهُ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَلَا تَكُونُواْ مِنَ ٱلۡمُشۡرِكِينَ ٣١ مِنَ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗاۖ كُلُّ حِزۡبِۢ بِمَا لَدَيۡهِمۡ فَرِحُونَ ٣٢\nفإذا اختلفوا في أمور الدين الاختلاف الذي يقتضيه اختلاف الاجتهاد، أو اختلفوا في الآراء والسياسات لاختلاف العوائد؛ فليحذروا أن يجرهم ذلك الاختلاف إلى أن يكونوا شيعًا متعادين متفرقين. ابن عاشور:٢١/٩٦.\nما الفائدة التي يستفيدها المسلمون من ذم تفرق أهل الكتاب؟\nمِنَ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗاۖ كُلُّ حِزۡبِۢ بِمَا لَدَيۡهِمۡ فَرِحُونَ ٣٢\n(شيعًا) أي: فرقًا متحالفين؛ كل واحدة منهم تُشايع من دان بدينها على من خالفهم؛ حتى كفّر بعضهم بعضًا، واستباحوا الدماء والأموال، فعُلم قطعًا أنهم كلهم ليسوا على الحق. (فرحون) ظنًا منهم أنهم صادفوا الحق، وفازوا به دون غيرهم. البقاعي:١٥/٩٠- ٩١.\nوضح من خلال الآية خطر الافتراق في دين الله."],[408,"§الروم\nwords\nيَقنَطُونَيَيأَسُونَ مِن زَوَالِ البَلاَءِ.\nيَبسُطُيُوسِعُ.\nوَيَقدِرُيُضَيَّقُ.\nرِبًاقَرضًا مِنَ المَالِ بِقَصدِ الرِّبَا المُحَرَّمِ.\nلِيَربُوَلِيَزِيدَ.\ndeeds\nزُر أحد أقاربك، أو اتصل به، واطمئن على حاله.\nتصدق على مسكين، أو ادعه إلى منزلك، وأحسن ضيافته.\nأرسل رسالة تبيّن فيها أضرار الربا، أو المعاصي الاجتماعية، وغيرها.\nguid\nحكمة الله، وتدبيره في الرزق؛ توسعة وتقليلًا، وإدراك ذلك خاص بالمؤمنين.\nعليك بالإخلاص في نفقاتك؛ فليس كل صدقة مقبولة.\nإذا رأيت مصيبة وقعت، أو كوارث قد حلت، فتذكر ذنبًا وقع قبلها.\nrefl\nوَإِذَا مَسَّ ٱلنَّاسَ ضُرّٞ دَعَوۡاْ رَبَّهُم مُّنِيبِينَ إِلَيۡهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنۡهُ رَحۡمَةً إِذَا فَرِيقٞ مِّنۡهُم بِرَبِّهِمۡ يُشۡرِكُونَ ٣٣\nأي: إذا مس هؤلاء الكفار ضر من مرض وشدة دعوا ربهم؛ أي: استغاثوا به في كشف ما نزل بهم، مقبلين عليه وحده دون الأصنام؛ لعلمهم بأنه لا فرج عندها. ﴿ثُمَّ إِذَآ أَذَاقَهُم مِّنۡهُ رَحۡمَةً﴾ أي: عافية ونعمة، ﴿إِذَا فَرِيقٌ مِّنۡهُم بِرَبِّهِمۡ يُشۡرِكُونَ﴾ أي: يشركون به في العبادة. القرطبي: ١٦/٤٣٣.\nبيّن كيف عاب الله تعالى على من يذكره في الشدة وينساه في الرخاء.\nوَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ فَرِحُواْ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ ٣٦\nانظر كيف قال هنا: (وإذا)، وقال في الشر: ﴿وَإِن تُصِبۡهُمۡ سَيِّئَةٌ﴾؛ لأن (وإذا) للقطع بوقوع الشرط؛ بخلاف (إن) فإنها للشك في وقوعه؛ ففي ذلك إشارة إلى أن الخير الذي يصيب به عباده أكثر من الشرّ. ابن جزي: ٢/١٦٩.\nما وجه الدلالة في الآية على أن الخير الذي يصيب العباد أكثر من الشر؟\nوَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ ٣٦\nولما كانت المصائب مسببة عن الذنوب، قال منبهًا لهم على ذلك، منكرًا قنوطهم وهم لا يرجعون عن المعاصي التي عوقبوا بسببها: ﴿بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ﴾. البقاعي: ١٥/٩٥.\nعدد بعض الآثار المترتبة على الذنوب.\nوَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ ٣٦\nقَولُهُ ﴿بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ﴾ لتنبيهِهِم إِلَى أَنَّ ما يصيبهم من حالَة سيئة في الدنيا إِنمَا سببها أَفعالُهم الَّتي جعلَها اللَّه أَسبابًا لمُسببات مؤثرة، لا يحيطُ بِأَسرارِها ودقَائقها إِلا اللَّه تعالَى، فَما علَى الناسِ إِلا أَن يحَاسبوا أَنفُسهم، ويجروا أَسباب إِصابةِ السيئات، ويتداركُوا ما فَات، فَذلكَ أَنجَى لَهم من السيئات وأَجدر من القُنوط. وهذا أَدب جليل من آداب التنزِيلِ؛ قَال تعالَى: ﴿مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَ﴾ [النساء: ٧٩]. ابن عاشور: ٢١/١٠١.\nما سبب المصائب التي تصيب الإنسان في الدنيا؟\nوَمَآ ءَاتَيۡتُم مِّن رِّبٗا لِّيَرۡبُوَاْ فِيٓ أَمۡوَٰلِ ٱلنَّاسِ فَلَا يَرۡبُواْ عِندَ ٱللَّهِۖ وَمَآ ءَاتَيۡتُم مِّن زَكَوٰةٖ تُرِيدُونَ وَجۡهَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُضۡعِفُونَ ٣٩\nقال الشعبي: \"معنى الآية: أن ما خدم الإنسان به أحدًا وخف له لينتفع به في دنياه، فإن ذلك النفع الذي يجزي به الخدمة لا يربو عند الله\". القرطبي: ١٦/٤٣٨.\nهل يثاب العبد على إعانته لأحد إذا كان يرجو بها الثواب الدنيوي فقط؟\nظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ لِيُذِيقَهُم بَعۡضَ ٱلَّذِي عَمِلُواْ لَعَلَّهُمۡ يَرۡجِعُونَ ٤١\nفسبحان مَن أنعم ببلائه، وتفضل بعقوبته، وإلا فلو أذاقهم جميع ما كسبوا ما ترك على ظهرها من دابة. السعدي: ٦٤٣.\nحتى في البلاء نعمة وفضل من الله -سبحانه وتعالى- فما وجه ذلك؟\nظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ\nفظهور الفساد في البر بالقحط، والفتن، وشبه ذلك، وظهور الفساد في البحر بالغرق، وقلة الصيد، وكساد التجارات، وشبه ذلك، وكل ذلك بسبب ما يفعله الناس من الكفر والعصيان. ابن جزي: ٢/١٦٩.\nما علامات ظهور الفساد؟ وما سببه؟"],[409,"§الروم\nwords\nلاَّ مَرَدَّ لَهُلاَ يَقدِرُ أَحَدٌ عَلَى رَدِّهِ.\nيَصَّدَّعُونَيَتَفَرَّقُ الخَلاَئِقُ أَشتَاتًا، ثُمَّ مَآلُهُم إِلَى الجَنَّةِ، أَوِ النَّارِ.\nيَمهَدُونَيُهَيِّئُونَ مَنَازِلَهُم فِي الجَنَّةِ.\nفَتُثِيرُتُحَرِّكُ، وَتَنشُرُ.\nكِسَفًاقِطَعًا مُتَفَرِّقَةً.\ndeeds\nاكتب رسالة عن الاستقامة وأهميتها، وأرسلها إلى زملائك.\nإذا رأيت ريحًا أو سحابًا فقل ما ورد في السنّة: \"اللَّهم إِني أَسأَلُكَ خيرها، وخيرِ ما فيها، وخير ما أُرسِلَت به، وأَعوذ بك من شرها، وشر ما فيها، وشر ما أُرسلَت بِه\".\nتأمل ثلاثًا من آثار رحمة الله عليك وعلى من حولك، ثم اشكر الله تعالى.\nguid\nالجزاء من جنس العمل.\nاعلم أن ثواب الله تعالى لعباده المؤمنين أعظم وأكبر مما عملوه؛ فهو يجازيهم بفضله ورحمته الواسعة.\nإياك واليأس؛ فإن الله ناصر دينه.\nrefl\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ\nوالأمر بالسير في الأرض يدخل فيه السير بالأبدان، والسير في القلوب؛ للنظر والتأمل بعواقب المتقدمين. السعدي:٦٤٣.\nهل السير في الأرض للتأمل مقتصر على السفر؟\nفَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِينَ ٤٢\nفاحذروا أن تفعلوا فِعَالهم، يُحذَى بكم حذوهم؛ فإن عدل الله وحكمته في كل زمان ومكان. السعدي:٦٤٣.\nما الذي يفيده الإنسان من تأمل عاقبة من قبله؟\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِينَ ٤٢\nوقوله تعالى: ﴿كَانَ أَكۡثَرُهُم مُّشۡرِكِينَ﴾ استئناف للدلالة على أن الشرك وحده لم يكن سبب تدمير جميعهم، بل هو سبب للتدمير في أكثرهم، وما دونه من المعاصي سبب له في قليل منهم. وجوَّز أن يكون للدلالة على أن سوء عاقبتهم لفشو الشرك وغلبته فيهم؛ ففيه تهويل لأمر الشرك بأنه فتنة لا تصيب الذين ظلموا خاصة. الألوسي:١١/٤٩.\nما أسباب هلاك الأمم؟ وما أعظمها؟\nإِنَّهُۥ لَا يُحِبُّ ٱلۡكَٰفِرِينَ ٤٥\nومع هذا هو العادل فيهم؛ الذي لا يجور. ابن كثير: ٣/٤٢٠.\nهل يترتب على عدم المحبة تسويغ الظلم؟\nوَمِنۡ ءَايَٰتِهِۦٓ أَن يُرۡسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٖ وَلِيُذِيقَكُم مِّن رَّحۡمَتِهِۦ\nفيُنَزِّل عليكم من رحمته مطرًا تحيا به البلاد والعباد، وتذوقون من رحمته ما تعرفون أن رحمته هي المنقذة للعباد، والجالبة لأرزاقهم؛ فتشتاقون إلى الإكثار من الأعمال الصالحة الفاتحة لخزائن الرحمة. السعدي:٦٤٣.\nكيف يتأثر المسلم عندما يتذوق رحمة الله -سبحانه وتعالى-؟\nوَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَٱنتَقَمۡنَا مِنَ ٱلَّذِينَ أَجۡرَمُواْۖ وَكَانَ حَقًّا عَلَيۡنَا نَصۡرُ ٱلۡمُؤۡمِنِينَ ٤٧\n﴿وَكَانَ حَقًّا عَلَيۡنَا نَصۡرُ ٱلۡمُؤۡمِنِينَ﴾ وإنجاؤهم من العذاب؛ ففي هذا تبشير للنبي -صلى الله عليه وسلم- بالظفر في العاقبة والنصر على الأعداء؛ قال الحسن: \"أنجاهم مع الرسل من عذاب الأمم\". البغوي:٣/٥٠٠.\nهل تسلط أهل الباطل لزمنٍ طويل يسوغ للمؤمن اليأس؟ وضح هذا من الآية.\nوَإِن كَانُواْ مِن قَبۡلِ أَن يُنَزَّلَ عَلَيۡهِم مِّن قَبۡلِهِۦ لَمُبۡلِسِينَ ٤٩ فَٱنظُرۡ إِلَىٰٓ ءَاثَٰرِ رَحۡمَتِ ٱللَّهِ كَيۡفَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ ذَٰلِكَ لَمُحۡيِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٥٠\n﴿مِّن قَبۡلِهِۦ﴾: كرر للتأكيد، وليفيد سرعة تقلب قلوب الناس من القنوط إلى الاستبشار. ابن جزي:٢/١٧٠.\nما السر في مجيء ﴿مِن قَبۡلُۖ﴾، ثم مجيئها مرة أخرى: ﴿مِّن قَبۡلِهِۦ﴾ في الآية نفسها؟"],[410,"§الروم\nwords\nمُصفَرًّاصَارَ أَصفَرَ بَعدَ خُضرَتِهِ؛ مِنَ الفَسَادِ.\nوَشَيبَةًشَيخُوخَةً، وَهَرَمًا.\nيُؤفَكُونَيُصرَفُونَ عَنِ الحَقِّ.\nوَلاَ هُم يُستَعتَبُونَلاَ يُطلَبُ مِنهُم إِرضَاءُ اللهِ بِالطَّاعَةِ وَالتَّوبَةِ.\nوَلاَ يَستَخِفَّنَّكَلاَ يَستَفِزَّنَّكَ، وَلاَ يَحمِلَنَّكَ عَلَى الخِفَّةِ، وَالطَّيشِ.\ndeeds\nسَلِ الله تعالى حسن الخاتمة.\nتب إلى الله سبحانه من كل ذنوبك قبل أن يأتي يوم لا تنفع فيه التوبة.\nادع الله تعالى أن يجعل قلبك سليمًا، وأن يثبت قلبك على دينه.\nguid\nاحذر أن تضيع قوة شبابك وصحتك في غفلة ولهو.\nالعلم عطية من الله تعالى، والجهد والذكاء مجرد سبب، فأكثر من قولك: \"رب زدني علمًا\".\nأسوأ أحوال الإنسان عندما يطبع على قلبه لكثرة ذنوبه؛ فيصبح لا يفهم، ولا يعقل شيئًا.\nrefl\n۞ٱللَّهُ ٱلَّذِي خَلَقَكُم مِّن ضَعۡفٖ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفٖ قُوَّةٗ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةٖ ضَعۡفٗا وَشَيۡبَةٗۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ ٥٤\nوذكر وصف العلم والقدرة؛ لأن التطور هو مقتضى الحكمة؛ وهي من شؤون العلم. ابن عاشور:٢١/١٢٨.\nما مناسبة ختام الآية الكريمة بصفتي: ﴿ٱلۡعَلِيمُ ٱلۡقَدِيرُ﴾ ؟\n۞ٱللَّهُ ٱلَّذِي خَلَقَكُم مِّن ضَعۡفٖ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفٖ قُوَّةٗ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةٖ ضَعۡفٗا وَشَيۡبَةٗۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ ٥٤\n﴿خَلَقَكُم مِّن ضَعۡفٍ﴾ الضعف الأول: كون الإنسان من ماء مهين، وكونه ضعيفًا في حال الطفولية، والضعف الثاني الأخير الهرم. ابن جزي:٢/١٧١.\nوضح ما المراد بالضعفين الواردين في الآية.\nوَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُواْ غَيۡرَ سَاعَةٖۚ\nيخبر تعالى عن جهل الكفار في الدنيا والآخرة؛ ففي الدنيا فعلوا ما فعلوا من عبادة الأوثان، وفي الآخرة يكون منهم جهل عظيم أيضًا؛ فمنه: إقسامهم بالله أنهم ما لبثوا غير ساعة واحدة في الدنيا، ومقصودهم بذلك: عدم قيام الحجة عليهم، وأنهم لم ينظروا حتى يعذر إليهم. ابن كثير:٣/٤٢٤.\nدلَّت الآية على جهل الكفار في الدنيا والآخرة، بَيِّن ذلك.\nوَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَٱلۡإِيمَٰنَ لَقَدۡ لَبِثۡتُمۡ فِي كِتَٰبِ ٱللَّهِ إِلَىٰ يَوۡمِ ٱلۡبَعۡثِۖ فَهَٰذَا يَوۡمُ ٱلۡبَعۡثِ وَلَٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ ٥٦\nوعطف الإيمان على العلم للاهتمام به؛ لأن العلم بدون إيمان لا يرشد إلى العقائد الحق التي بها الفوز في الحياة الآخرة. ابن عاشور:٢١/١٣١.\nلماذا عطف الإيمان على العلم في الآية الكريمة؟\nكَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعۡلَمُونَ ٥٩\nأي: يختم (الله) الذي جلت عظمته وعظمت قدرته ﴿عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعۡلَمُونَ﴾ أي: لا يطلبون العلم ولا يتحرون الحق، بل يصرون على خرافات اعتقدوها وترهات ابتدعوها؛ فإن الجهل المركب يمنع إدراك الحق، ويوجب تكذيب المحق، ومن هنا قالوا: هو شر من الجهل البسيط. الألوسي:١١/٦٠- ٦١.\nبيّن خطر عدم تحري الحق، والإصرار على الجهل.\nفَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۖ\nوهذا مما يعين على الصبر؛ فإن العبد إذا علم أن عمله غير ضائع، بل سيجده كاملًا؛ هان عليه ما يلقاه من المكاره، ويسر عليه كل عسير. السعدي:٦٤٦.\nلماذا ذكر الصبر قبل ذكر الله أن وعده حقٌ؟\nوَلَا يَسۡتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ ٦٠\nوهذا مما يدل على أن كل مؤمن موقن: رزين العقل، يسهل عليه الصبر، وكل ضعيف اليقين: ضعيف العقل، خفيفه؛ فالأول بمنزلة اللب، والآخر بمنزلة القشور. السعدي:٦٤٦.\nهذه الآية تدل على اختلاف عقول من يقع عليهم الابتلاء، بَيِّن ذلك."],[411,"§لقمان\nwords\nهُزُوًاسُخرِيَةً.\nوَقرًاصَمَمًا.\nرَوَاسِيَجِبَالًا ثَابِتَةً.\nأَن تَمِيدَ لِئَلاَّ تَضطَرِبَ وَتَتَحَرَّكَ.\nوَبَثَّنَشَرَ.\ndeeds\nأدّ الصلوات الخمس في جماعة مع إدراك تكبيرة الإحرام.\nأرسل رسالة تبين فيها خطر الغناء، وأنه يضل عن سبيل الله.\nاستعذ بالله من الاستكبار على خلق الله، أو على الانقياد للشرع.\nguid\nمن ثمرات اتباع القرآن التي يتحصّل عليها العبد: الهدى والرحمة، وتحصيل مرتبة الإحسان.\nمن استمع الغناء انصرف قلبه عن حب القرآن.\nالتواضع يعين على اتباع الحق بعكس الكبر.\nrefl\nتِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ ٢ هُدٗى وَرَحۡمَةٗ لِّلۡمُحۡسِنِينَ ٣\nولكن مع أنه حكيم، يدعو إلى كل خلق كريم، وينهى عن كل خلق لئيم؛ أكثر الناس محرومون الاهتداء به، معرضون عن الإيمان والعمل به، إلا من وفقه الله تعالى وعصمه، وهم المحسنون في عبادة ربهم، والمحسنون إلى الخلق. السعدي:٦٤٦.\nما موقف الناس من هذا الكتاب الحكيم؟\nٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ\nخَصَّ من العمل عملين فاضلين: الصلاة؛ المشتملة على الإخلاص، ومناجاة الله تعالى، والتعبد العام للقلب واللسان والجوارح، المعينة على سائر الأعمال، والزكاة؛ التي تزكي صاحبها من الصفات الرذيلة، وتنفع أخاه المسلم، وتسد حاجته، ويبين بها أن العبد يؤثر محبة الله على محبته للمال؛ فيخرج محبوبه من المال لما هو أحب إليه، وهو طلب مرضاة الله. السعدي:٦٤٦\nلماذا خُصَّ هذان العملان دون سائر الأعمال؟\nٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ ٤\n(الذين يقيمون الصلاة) أي: يجعلونها كأنها قائمة؛ بفعلها بسبب إتقان جميع ما أمر به فيها، ونُدب إليه، وتوقفت بوجه عليه؛ على سبيل التجديد في الأوقات المناسبة لها والاستمرار. البقاعي:١٥/١٤٤.\nما الذي أفاده التعبير بِــ(يقيمون الصلاة)؟\nوَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ٦\nقال أبو الصهباء البكري: سألت ابن مسعود عن هذه الآية فقال: \"هو الغناء، والله الذي لا إله إلا هو\"؛ يرددها ثلاث مرات. وقال إبراهيم النخعي: \"الغناء ينبت النفاق في القلب\"،... وقيل: \"الغناء رقية الزنا\". البغوي:٣/٥٠٦.\nمن خلال هذه الآية: بيّن مفاسد الغناء، وخطره من كلام السلف.\nوَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ٦\n﴿لَهۡوَ ٱلۡحَدِيثِ﴾ أي: ما يلهي من الأشياء المتجددة التي تستلذ، فيقطع بها الزمان من: الغناء، والمضحكات، وكل شيء لا اعتبار فيه؛ فيوصل النفس بما أوصلها إليه من اللذة إلى مجرد الطبع البهيمي، فيدعوها إلى العبث من اللعب؛ كالرقص، ونحوه...فينزل إلى أسفل سافلين كما علا الذي قبله بالحكمة إلى أعلى عليين. البقاعي:١٥/١٤٦.\nما خطر الانزلاق مع الملهيات؟\nوَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّخِذَهَا هُزُوًاۚ\nقال قتادة: \"والله لعله لا ينفق فيه مالًا، ولكن شراءه استحبابه، بحسب المرء من الضلالة أن يختار حديث الباطل على حديث الحق، وما يضر على ما ينفع\". ابن كثير:٣/٤٢٦.\nهل يلزم من دخول المرء في هذه الآية أن يكون قد دفع مالًا في شراء لهو الحديث؟\nأُوْلَٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ٦\nأَي: كمَا استهانوا بآيات الله وسبيله أهينوا يوم القيامة في العذاب الدائم المستمر. ابن كثير:٣/٤٢٦.\nجزاء هؤلاء كان من جنس عملهم، وضح ذلك."],[412,"§لقمان\nwords\nوَهنًاضَعفًا.\nوَفِصَالُهُفِطَامُهُ عَنِ الرَّضَاعَةِ.\nأَنَابَرَجَعَ، وَتَابَ.\nحَبَّةٍ مِن خَردَلٍحَبَّةٍ صَغِيرَةٍ مُتَنَاهِيَةٍ فِي الصِّغَرِ.\nمِن عَزمِ الأُمُورِمِنَ الأُمُورِ الَّتِي يَنبَغِي الحِرصُ عَلَيهَا.\nوَلاَ تُصَعِّر خَدَّكَلاَ تُمِل وَجهَكَ كِبرًا وَتَعَاظُمًا.\nمَرَحًامُختَالًا مُتَبَختِرًا.\ndeeds\nأَدِّ اليوم أحد الأعمال المنزلية التي تتولاها أمك حتى تعرف صبرها وفضلها.\nذَكِّر من تراهم جالسين في الطرقات وقت الصلاة بأداء الصلاة.\nتكلم بصوت منخفض، ولا تكن صخابًا مزعجًا.\nguid\nلا طاعة لمخلوق في معصية الخالق، وهذا لا ينافـي بر الوالدين في غير المعصية.\nاتبع سبيل من أناب إلى الله -سبحانه وتعالى- من العلماء الربانيين.\nاحذر ذنوب الخلوات.\nrefl\nوَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدٞ ١٢\nكان أول ما لُقنه لقمان من الحكمة هو الحكمة في نفسه؛ بأن أمره الله بشكره على ما هو محفوف به من نعم الله، التي منها نعمة الاصطفاء. ابن عاشور:٢١/١٥٢.\nما أول حكمة لقمان -عليه السلام- من خلال الآية الكريمة؟\nوَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمٞ ١٣\nابتدأ لقمان موعظة ابنه بطلب إقلاعه عن الشرك بالله؛ لأن النفس المعرّضة للتزكية والكمال يجب أن يقدم لها قبل ذلك تخليتُها عن مبادئ الفساد والضلال. ابن عاشور:٢١/١٥٥.\nلماذا ابتدأ لقمان -عليه السلام- بنهي ابنه عن الشرك؟\nوَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ\nيوصي ولده الذي هو أشفق الناس عليه، وأحبهم إليه؛ فهو حقيق أن يمنحه أفضل ما يعرف. ابن كثير:٣/٤٢٨.\nما الفائدة من كون الوصايا كانت لابنه؟\nوَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنٖ وَفِصَٰلُهُۥ فِي عَامَيۡنِ\nوإنَّما يذكر تعالى تربية الوالدة، وتعبها، ومشقتها في سهرها ليلًا ونهارًا؛ ليذكر الولد بإحسانها المتقدم إليه. ابن كثير:٣/٤٢٩.\nلماذا ذكر -سبحانه وتعالى- مشقة الوالدة في تربية ولدها؟\nأَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ ١٤\nقيل: الشكر لله على نعمة الإيمان، وللوالدين على نعمة التربية. وقال سفيان بن عيينة: \"من صلى الصلوات الخمس فقد شكر الله تعالى، ومن دعا لوالديه في أدبار الصلوات فقد شكرهما\". القرطبي:١٦/٤٧٥\nكيف يكون شكر الله تعالى وشكر الوالدين؟\nوَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ\nعَلِمَ أن الآمر بالمعروف والناهي عن المنكر لا بد أن يناله من الناس أذى؛ فأمره بالصبر. ابن كثير:٣/٤٣٠.\nلماذا أمره بالصبر بعد أن أمره بالأمر بالمعروف والنهي عن المنكر؟\nوَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ ١٩\nأي: ليكن مشيك قصدًا؛ لا تخيُّلًا، ولا إسراعًا. وقال عطاء: \"امش بالوقار والسكينة\"، كقوله: ﴿يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا﴾ [الفرقان: ٦٣]. البغوي:٣/٥١١.\nكيف تكون الحكمة في المشي؟"],[413,"§لقمان\nwords\nسَخَّرَ لَكُمذَلَّلَ لَكُم.\nوَأَسبَغَعَمَّكُم بِنِعَمِهِ.\nبِالعُروَةِ الوُثقَىأَوثَقِ سَبَبٍ مُوصِلٍ إِلَى رِضوَانِ اللهِ.\nعَاقِبَةُمَآلُ، وَمَرجِعُ.\nغَلِيظٍفَظِيعٍ ثَقِيلٍ.\ndeeds\nاختر سورة من القرآن وطبق عليها المراتب الثلاث لطلب العلم، وهي: أ - تأمُّل ما فيها من فوائد. ب- تدارس السورة مع من هو أعلم منك. ج - قراءة تفسيرها من أحد كتب التفسير.\nاكتب في ورقة بعض النعم الظاهرة والباطنة عليك؛ ليعينك ذلك على الشكر.\nأرسل رسالة تبين فيها خطر الجدال بغير علم.\nguid\nالتقليد الأعمى وتعطيل العقل مضرة.\nالتمسك بالدين هو حبل النجاة وصمام الأمان.\nالعبد مكلّف بتبليغ دعوة الله، أما النتائج فأمرها إلى الله.\nrefl\nأَلَمۡ تَرَوۡاْ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ\nفوظيفتكم أن تقوموا بشكر هذه النعم؛ بمحبة المنعم والخضوع له، وصرفها في الاستعانة على طاعته، وأن لا يستعان بشيء منها على معصيته. السعدي:٦٤٩.\nكيف يكون شكر النعم؟\nوَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ\n﴿نِعَمَهُۥ ظَٰهِرَةً وَبَاطِنَةًۗ﴾ الظاهرة: الصحة، والمال، وغير ذلك. والباطنة: النعم التي لا يطلع عليها الناس، ومنها ستر القبيح من الأعمال. ابن جزي:٢/١٧٤.\nمثّل لبعض النعم الظاهرة والباطنة.\nوَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةٗ وَبَاطِنَةٗۗ\nعن ابن عباس: \"النعمة الظاهرة: الإسلام والقرآن، والباطنة: ما ستر عليك من الذنوب ولم يعجل عليك بالنقمة\"، وقال الضحاك: \"الظاهرة: حسن الصورة، وتسوية الأعضاء، والباطنة: المعرفة\". القرطبي:٣/٥١٢\nاذكر اثنتين من النعم التي تعتقد أن الله سبحانه اختصك بها.\nوَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ ٢٠\nوشمل قوله ﴿بِغَيۡرِ عِلۡمٍ وَلَا هُدًى وَلَا كِتَٰبٍ مُّنِيرٍ﴾ مراتبَ اكتساب العلم، وهي: إما الاجتهاد والاكتساب، أو التلقي من العالم، أو مطالعة الكتب الصائبة. ابن عاشور:٢١/١٧٥.\nاشتملت الآية الكريمة على مراتب اكتساب العلم الثلاث بينها.\n۞وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ ٢٢\nأي: يخلص عبادته وقصده إلى الله تعالى، ﴿وَهُوَ مُحۡسِنٌ﴾؛ لأن العبادة من غير إحسان ولا معرفة القلب لا تنفع. القرطبي:١٦/٤٨٧.\nكيف تسلم وجهك لله تعالى؟ ولم قيد ذلك بالإحسان؟\n۞وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ ٢٢\nومناسبته هنا أن كفر المشركين بعضُه إعلان، وبعضه إسرار. ابن عاشور:٢١/١٧٨.\nما مناسبة ختام الآية الكريمة بقوله تعالى: ﴿إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ﴾؟\nوَلَوۡ أَنَّمَا فِي ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَٰمٞ وَٱلۡبَحۡرُ يَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرٖ مَّا نَفِدَتۡ كَلِمَٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ٢٧\nالآية إخبار بكثرة كلمات الله، والمراد: اتساع علمه، ومعنى الآية: أن شجر الأرض لو كانت أقلامًا، والبحر لو كان مدادًا يصب فيه سبعة أبحر صَبًّا دائمًا، وكتبت بذلك كلمات الله؛ لنفدت الأشجار والبحار، ولم تنفد كلمات الله؛ لأن الأشجار والبحار متناهية، وكلمات الله غير متناهية. ابن جزي:٢/١٧٥.\nاذكر فائدة من هذه الآية."],[414,"§لقمان\nwords\nيُولِجُيُدخِلُ؛ بِأَن يَأخُذَ مِن سَاعَاتِ اللَّيلِ فَيطُولَ النَّهَارُ، وَالعَكسِ.\nغَشِيَهُمعَلاَهُم.\nكَالظُّلَلِكَالسَّحَابِ، أَوِ الجِبَالِ المُظِلَّةِ.\nخَتَّارٍغَدَّارٍ نَاقِضٍ لِلعَهدِ.\ndeeds\nشاهد صورًا عن السفن، أو اقرأ شيئًا عنها؛ لتتعرف على عظيم نعمة الله علينا بها.\nتذكر موقفًا صعبًا نجاك الله منه، واحمد الله على نعمة النجاة، ثم اعمل عملًا صالحًا شكرًا لله.\nتذكر شيئًا من زينة الدنيا تعلق به قلبك، ثم اكتب ثلاثة من عيوبه؛ حتى يخف تعلقك به.\nguid\nبعض مشركي هذا الزمان أشد من كفار قريش؛ لأنهم يشركون في الرخاء والشدة، أما مشركو قريش فكانوا يشركون في الرخاء، ويوحّدون في الشدة.\nادّعاء علم الغيب كفر، ومن يزعم أنّ أحدًا من الأنبياء والأولياء يعلم الغيب فقد ادّعى مشاركة المخلوق للخالق.\nاحذر التسويف، وعليك بالعمل.\nrefl\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِيٓ إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِيرٞ ٢٩\nوالابتداء بالليل؛ لأن أمره أعجب؛ كيف تغشَى ظُلمته تلك الأنوار النهارية؟! ابن عاشور:٢١/١٨٥.\nلماذا ابتدأت الآية الكريمة بالليل؟\nأَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ٣١\nووجه إيثار خلقي الصبر والشكر هنا للكناية بهما، من بين شعب الإيمان، أنهما أنسب بمقام السير في البحر؛ إذ راكب البحر بين خطر وسلامة، وهما مظهر الصبر والشكر. ابن عاشور:٢١/١٩٠.\nما وجه إيثار خلقي الصبر والشكر عند ذكر جريان الفلك في البحر؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ٣١\nأي: صبار لقضائه، شكور على نعمائه. وقال أهل المعاني: أراد لكل مؤمن بهذه الصفة؛ لأن الصبر والشكر من أفضل خصال الإيمان. القرطبي:١٦/٤٩٣.\nلم ختم الآية بهذين الوصفين العظيمين؟\nأَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ٣١\nمبالغ في كل من الصبر والشكر. وعُلم من صيغة المبالغة في كل منهما أنه لا يعرِف في الرخاء من عظمة الله ما كان يعرفه في الشدة إلا مَنْ طبَعَهم الله على ذلك ووفقهم له وأعانهم عليه؛ بحفظ العهد، وترك النقض؛ جريًا مع ما تدعو إليه الفطرة الأولى السليمة، وقليل ما هم. البقاعي:١٥/٢٠٦.\nما الذي يفيده ختم الآية بصفتي الصبر والشكر بصيغة المبالغة؟\nوَإِذَا غَشِيَهُم مَّوۡجٞ كَٱلظُّلَلِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدٞۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٖ كَفُورٖ ٣٢\n(ختَّار) أي: غدّار، شديد الغدر؛ وذلك أنه جحد نعمة الله غدرًا. ابن جزي:٢/١٧٦\nلمَ كان الكافر شديد الغدر؟\nيَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡ وَٱخۡشَوۡاْ يَوۡمٗا لَّا يَجۡزِي وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيۡـًٔاۚ\nيأمر تعالى الناس بتقواه؛ التي هي امتثال أوامره وترك زواجره، ويستلفتهم لخشية يوم القيامة؛ اليوم الشديد، الذي فيه كل أحد لا يهمه إلا نفسه ف(لا يجزي والد عن ولده ولا مولود هو جازٍ عن والده شيئًا): لا يزيد في حسناته ولا ينقص من سيئاته؛ قد تم على كل عبد عمله، وتحقق عليه جزاؤه. فلفت النظر في هذا لهذا اليوم الـمُهِيْل مما يقوي العبد، ويسهِّل عليه تقوى الله. السعدي:٦٥٢.\nلماذا أكثر الله من ذكر أهوال يوم القيامة في القرآن؟\nإِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلۡغَيۡثَ وَيَعۡلَمُ مَا فِي ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِي نَفۡسٞ مَّاذَا تَكۡسِبُ غَدٗاۖ وَمَا تَدۡرِي نَفۡسُۢ بِأَيِّ أَرۡضٖ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرُۢ ٣٤\nولُقِّبت هذه الخمسة في كلام النبي -صلى الله عليه وسلم- بمفاتح الغيب، وفسر بها قوله تعالى: ﴿وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَ﴾ [الأنعام:٥٩]؛ ففي صحيح البخاري من حديث ابن عمر قال رسول الله -صلى الله عليه وسلم-: «مَفاتح الغيب خمس» ثم قرأ: ﴿إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ﴾. ابن عاشور:٢١/١٩٨.\nبماذا تسمى الأمور الخمسة المذكورة في الآية الكريمة؟"],[415,"§السجدة\nwords\nافتَرَاهُاختَلَقَهُ مِن عِندِ نَفسِهِ.\nاستَوَىعَلاَ وَارتَفَعَ؛ استِوَاءً يَلِيقُ بِجَلاَلِهِ وَعَظَمَتِهِ.\nيَعرُجُ إِلَيهِيَصعَدُ إِلَيهِ.\nنَسلَهُذُرِّيَّتَهُ.\nسُلاَلَةٍوَهِيَ النُّطفَةُ؛ لأِنَّهَا مُستَلَّةٌ مِن جَمِيعِ البَدَنِ.\nمَهِينٍضَعِيفٍ، رَقِيقٍ.\nضَلَلنَا فِي الأَرضِتَحَوَّلنَا تُرَابًا بَعدَ المَوتِ.\ndeeds\nذكّر إمام مسجدك بقراءة سورة السجدة مع سورة الإنسان فجر الجمعة؛ فإنها سنّة.\nادع الله تعالى أن يدبّر لك أمورك، وأن يرزقك العلم النافع، فهو المدبر والعليم.\nادع الله أن يحسِّن خُلُقَك كما حسّن خلقَك.\nguid\nفي الآية بيان لعظيم قدرة الله في تدبير الأمور.\nالسمع والبصر نعمتان، وشكرهما يكون باستعمالهما فيما يقرّب إلى الله.\nتذكر لحظة الوفاة التي تقابل الله تعالى فيها بعملك؛ إن خيرًا، أو شرًا.\nrefl\nالٓمٓ ١ تَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ٢\nعَن أَبِي هُرَيرَةَ -رضي الله عَنهُ- قَالَ: كان النبي -صلى الله عليه وسلم- يقرأ فِي الفجر يومَ الجُمُعَةِ: ﴿الٓمٓ * تَنزِيلُ﴾ السجدةَ، و﴿هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ﴾. ابن كثير:٦/٣٥٨.\nتأمل سورة السجدة، ثم حاول أن تبين الحكمة من استحباب قراءتها في فجر الجمعة.\nتَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ٢\nنزل من رب العالمين؛ الذي رباهم بنعمته، ومن أعظم ما رباهم به هذا الكتاب؛ الذي فيه كل ما يصلح أحوالهم، ويتمم أخلاقهم. السعدي:٦٥٣.\nما المقصود بوصف الربوبية في قوله تعالى: ﴿رَبِّ ٱلۡعَٰلَمِينَ﴾؟\nتَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ٢\nافتتحت السورة بالتنويه بشأن القرآن؛ لأنه جامع الهدى الذي تضمنته هذه السورة وغيرها، ولأن جماع ضلال الضالّين هو التكذيب بهذا الكتاب، فالله جعل القرآن هدى للناس، وخصّ العرب أن شَرفهم بجعلهم أولَ من يتلقّى هذا الكتاب. ابن عاشور:٢١/٢٠٥.\nدلت الآية الكريمة على تعظيم شأن القرآن الكريم، بين ذلك.\nٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ ٤\nأي: ألا تسمعون هذه المواعظ؛ فلا تتذكرون بها، أو أتسمعونها؛ فلا تتذكرون بها، فالإنكار على الأول متوجه إلى عدم السماع، وعدم التذكر معا، وعلى الثاني إلى عدم التذكر مع تحقق ما يوجبه من السماع. الألوسي:١١/١١٨.\nمتى تتحقق الفائدة من سماع الموعظة؟\nمَا لَكُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ ٤\nيقول: ما لكم أيها الناس دونه ولي؛ يلي أمركم، وينصركم منه إن أراد بكم ضرًّا، ولا شفيع؛ يشفع لكم عنده إن هو عاقبكم على معصيتكم إياه. يقول: فإياه فاتخذوا وليًّا، وبه وبطاعته فاستعينوا على أموركم؛ فإنه يمنعكم -إذا أراد منعكم- ممن أرادكم بسوء، ولا يقدر أحد على دفعه عما أراد بكم هو؛ لأنه لا يقهره قاهر. الطبري:٢٠/١٦٦.\nلا يصح أن يتعلق القلب والجوارح إلا بالله وحده، وضّح ذلك من الآية.\nيُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةٖ مِّمَّا تَعُدُّونَ ٥\nفيه إشارة إلى أن تدبير العباد عند تدبيره -عز وجل- لا أثر له؛ فطوبى لمن رزق الرضا بتدبير الله تعالى واستغنى عن تدبيره. الألوسي: ١١/١٣٨.\nما فائدة التوكل على الله سبحانه؟\nذَٰلِكَ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلرَّحِيمُ ٦\nومناسبة وصفه تعالى ب ﴿ٱلۡعَزِيزُ ٱلرَّحِيمُ﴾ عقب ما تقدم: أنه خلق الخلق بمحض قدرته بدون معين؛ فالعزة -وهي الاستغناء عن الغير- ظاهرة، وأنه خلقهم على أحوال فيها لطف بهم؛ فهو رحيم بهم فيما خلقهم؛ إذ جعل أمور حياتهم ملائمة لهم، فيها نعيم لهم، وجنبهم الآلام فيها. ابن عاشور:٢١/٢١٥.\nما مناسبة وصفه تعالى ب ﴿ٱلۡعَزِيزُ ٱلرَّحِيمُ﴾ في الآية الكريمة؟"],[416,"§السجدة\nwords\nنَاكِسُوا رُؤُوسِهِمقَد خَفَضُوهَا، وَأَطرَقُوا خِزيًا وَنَدَمًا.\nحَقَّ القَولُثَبَتَ وَتَحَقَّقَ وَوَجَبَ.\nالجِنَّةِالجِنِّ.\nتَتَجَافَىتَرتَفِعُ، وَتَتَنَحَّى لِلعِبَادَةِ.\nالمَضَاجِعِفُرُشِ النَّومِ.\nمَا أُخفِيَ لَهُممَا ادُّخِرَ لَهُم مِنَ الجَزَاءِ.\nمِن قُرَّةِ أَعيُنٍمَا يُفرِحُ، وَيَسُرُّ.\nالمَأوَىالَّتِي يَأوُونَ إِلَيهَا، وَيُقِيمُونَ بِهَا.\nنُزُلًاضِيَافَةً لَهُم.\ndeeds\nاسجد سجدة تلاوة عند قراءة هذه الآية.\nاضبط منبّهك لتقوم وتصلي من الليل وتدعو ربك.\nتصدق بصدقة.\nguid\nاعمل الصالحات قبل أن تتمنى عملها ولا تستطيع.\nالهداية بيد الله تعالى، فاسأل الله إياها.\nليكن لك خبيئة عمل صالح، فاعمل عملًا صالحًا لا يطّلع عليه إلا الله.\nrefl\nوَلَوۡ تَرَىٰٓ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُواْ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَٰلِحًا إِنَّا مُوقِنُونَ ١٢\nولو ترى حال المجرمين في الآخرة؛ لرأيت أمرًا مهولًا. (ناكسوا رؤوسهم) عبارة عن الذل، والغم، والندم. ﴿رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا﴾ تقديره: يقولون: ربنا قد علمنا الحقائق. ابن جزي:٢/١٧٨.\nلماذا ينكِّس المجرمون رؤوسهم يوم القيامة؟\nإِنَّمَا يُؤۡمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدٗاۤ وَسَبَّحُواْ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ۩ ١٥\nأي: خروا سجدًا لله تعالى على وجوههم؛ تعظيمًا لآياته، وخوفًا من سطوته وعذابه. القرطبي:١٧/٢٧.\nما الحال التي ينبغي أن يكون عليها المؤمن عند تذكيره بآيات الله؟\nتَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ١٦\n﴿تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ﴾ أي: ترتفع. والمعنى: يتركون مضاجعهم بالليل من كثرة صلاتهم النوافل، ومن صلى العشاء والصبح في جماعة فقد أخذ بحظه من هذا. ابن جزي:٢/١٧٩.\nما الذي دفع بعض المؤمنين إلى ترك مضاجعهم؟\nتَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ١٦\n(وطمعًا) أي: في رضاه الموجب لثوابه، وعبر به دون الرجاء؛ إشارة إلى أنهم لشدة معرفتهم بنقائصهم لا يعدُّون أعمالهم شيئًا، بل يطلبون فضله بغير سبب، وإذا كانوا يرجون رحمته بغير سبب فهم مع السبب أرجى؛ فهم لا ييأسون من روحه. البقاعي:١٥/٢٥٦.\nلماذا عبر بالطمع بدل الرجاء؟\nتَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ١٦\n﴿وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾: ولما ذكر إيثارهم التقرب إلى الله على حظوظ لذاتهم الجسدية ذكر معه إيثارهم إياه على ما به نوال لَذات أخرى؛ وهو المال. ابن عاشور:٢١/٢٢٩.\nلماذا جاء قوله تعالى ﴿وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾ بعد الكلام عن قيام الليل؟\nفَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ\nأي: فلا يعلم أحدٌ عظمة ما أخفى الله لهم في الجنات من النعيم المقيم، واللذات التي لم يطلع على مثلها أحد؛ لمَّا أخفوا أعمالهم كذلك أخفى الله لهم من الثواب، جزاء وفاقًا؛ فإن الجزاء من جنس العمل. قال الحسن البصري: \"أخفى قوم عملهم فأخفى الله لهم ما لم تر عين، ولم يخطر على قلب بشر\". ابن كثير:٣/٤٤٣.\nلماذا أخفى الله الكثير من جزاء أهل الجنة؟\nكُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَآ أُعِيدُواْ فِيهَا\nفكلما حدثتهم إرادتهم بالخروج لبلوغ العذاب منهم كل مبلغ، رُدُّوا إليها، فذهب عنهم روح ذلك الفرج، واشتد عليهم الكرب. السعدي:٦٥٦.\nكيف يدل هذا الجزء من الآية على شدة عذابهم؟"],[417,"§السجدة\nwords\nالعَذَابِ الأَدنَىالبَلاَيَا وَالمَصَائِبِ فِي الدُّنيَا.\nمِريَةٍشَكٍّ.\nمِن لِقَائِهِلِقَاءِ مُوسَى -عليه السلام- لَيلَةَ الإِسرَاءِ.\nأَوَلَم يَهدِ لَهُمأَوَلَم يَتَبَيَّن لِهَؤُلاَءِ المُكَذِّبِينَ؟!\nالجُرُزِاليَابِسَةِ، الغَلِيظَةِ الَّتِي لاَ نَبَاتَ فِيهَا.\nيُنظَرُونَيُمهَلُونَ.\ndeeds\nتذكر ثلاثًا من المصائب والابتلاءات التي أنذر الله بها أهل بلدك، ثم ذكّر بها غيرك.\nتذكر مصيبة نزلت بك، ثم حاسب نفسك، وارجع إلى ربك.\nاستعرض من قصص القرآن خمسًا من صور العذاب الدنيوي التي عوقب بها العصاة.\nguid\nفي إهلاك الله تعالى للقرون السابقة أكبر واعظ لمن له قلب وبصيرة.\nاستعجال العذاب يدل على الجهل والطيش.\nالتوبة لا تقبل عند معاينة العذاب، أو مشاهدة ملك الموت ساعة الاحتضار.\nrefl\nوَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَآۚ إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ ٢٢\n﴿وَمَنۡ أَظۡلَمُ﴾ أي: لا أحد أظلم لنفسه، ﴿مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ﴾ أي: بحججه وعلاماته، ﴿ثُمَّ أَعۡرَضَ عَنۡهَآۚ﴾ بترك القبول، ﴿إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ﴾ لتكذيبهم وإعراضهم. القرطبي:١٧/٤٠-٤١.\nبيّن خطورة الإعراض عن مواعظ الله تعالى وعاقبته.\nوَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ ٢٤\nفيه إشارة إلى ما ينبغي أن يكون المرشد عليه من الأوصاف؛ وهو الصبر على مشاق العبادات، وأنواع البليات، وحبس النفس عن ملاذ الشهوات، والإيقان بالآيات؛ فمن يدعي الإرشاد وهو غير متصف بما ذُكر فهو ضالّ. الألوسي:١١/١٣٩.\nكيف يكون الداعية من أئمة الهدى؟\nوَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ\nسئل سفيان عن قول علي -رضي الله عنه-: \"الصبر من الإيمان بمنزلة الرأس من الجسد\"؛ فقال: \"ألم تسمع قوله: ﴿وَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةً يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ﴾\"؛ قال: \"لما أخذوا برأس الأمر صاروا رؤوسًا\". ابن كثير:٣/٤٤٦.\nمن أين جاء علي بن أبي طالب -رضي الله عنه- بهذا المعنى: \"الصبر من الإيمان بمنزلة الرأس من الجسد\"؟\nوَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ ٢٤\n﴿لَمَّا صَبَرُواْۖ﴾ أي: لصبرهم جعلناهم أئمة... وهذا الصبر صبر على الدين، وعلى البلاء، وقيل: صبروا عن الدنيا. القرطبي:١٧/٤٣\nما المقصود بالصبر في هذه الآية؟\nأَوَ لَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍۚ أَفَلَا يَسۡمَعُونَ ٢٦\n﴿إِنَّ فِي ذَٰلِكَ﴾ أي: فيما ذكر من إهلاكنا للأمم الخالية العاتية، أو في مساكنهم، (لآيات) عظيمة في أنفسها، كثيرة في عددها، ﴿أَفَلَا يَسۡمَعُونَ﴾ هذه الآيات سماع تدبر واتعاظ. الألوسي:١١/١٣٦.\nما فائدة ذكر أخبار الأمم الخالية؟\nقُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ يُنظَرُونَ ٢٩\nومن زعم أن المراد من هذا الفتح فتح مكة فقد أبعد النجعة، وأخطأ فأفحش؛ فإن يوم الفتح قد قَبِل رسول الله -صلى الله عليه وسلم- إسلام الطلقاء، وقد كانوا قريبًا من ألفين؛ ولو كان المراد فتح مكة لما قبل إسلامهم؛ لقوله تعالى: ﴿قُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ يُنظَرُونَ﴾، وإنَّما المراد: الفتح الذي هو القضاء والفصل. ابن كثير: ٣/٤٤٧.\nما المقصود بالفتح في هذه الآية؟\nفَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ ٣٠\nفأعرض عن سفههم، ولا تجبهم إلا بما أمرت به، ﴿وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ﴾ أي: انتظر يوم الفتح؛ يوم يحكم الله لك عليهم. القرطبي:١٧/٤٦.\nبيّن المنهج القرآني في التعامل مع المكذبين المعرضين؟"],[418,"§الأحزاب\nwords\nتُظَاهِرُونَ مِنهُنَّالظِّهَارُ: أَن يَقُولَ الرَّجُلُ لاِمرَأَتِهِ: أَنتِ عَلَيَّ كَظَهرِ أُمِّي.\nأَدعِيَاءَكُممَن تَبَنَّيتُ مُوهُ مِن أَولاَدِ غَيرِكُم.\nوَمَوَالِيكُمأَولِيَاؤُكُم فِي الدِّينِ.\nجُنَاحٌإِثمٌ.\nأَولَى بِالمُؤمِنِينَ أَنفَعُ، وَأَرأَفُ، وَأَقرَبُ لَهُم مِن أَنفُسِهِم فِي الدِّينِ وَالدُّنيَا.\nوَأَزوَاجُهُ أُمَّهَاتُهُممِثلُ أُمَّهَاتِهِم؛ فِي تَحرِيمِ نِكَاحِهِنَّ، وَتَعظِيمِ حَقِّهِنَّ.\ndeeds\nقل: \"حسبي الله، لا إله إلا هو، عليه توكلت، وهو رب العرش العظيم\".\nترضَّ عن أمهات المؤمنين، وتعرَّف على حقوقهن.\nزُر بعض أرحامك، وصلهم بأي نوع من أنواع الصلة.\nguid\nأمر الله لنبيه بالتقوى حتى لا يأنف أحدٌ عن النصيحة والتذكير.\nالكافرون والمنافقون لا يصلحون للاستشارة في أمر من أمور الدين.\nمن توكل على الله جعل الله له من كل هم فرجًا، ومن كل ضيق مخرجًا، ومن كل بلاء عافية.\nrefl\nيَٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ١\n(يا أيها النبي): نداء فيه تكريم له؛ لأنه ناداه بالنبوّة، ونادى سائر الأنبياء بأسمائهم. ابن جزي:٢/١٨١.\nكيف كان النداء للنبي -صلى الله عليه وسلم- في هذه الآية نداء تكريم؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ\nهذا تنبيه بالأعلى على الأدنى؛ فإنه تعالى إذا كان يأمر عبده ورسوله بهذا؛ فلأن يأتمر مَن دونه بذلك بطريق الأولى والأحرى. ابن كثير:٣/٤٤٨.\nهل يستغني أحد عن الأمر بالتقوى والنهي عن طاعة الكافرين والمنافقين؟\nوَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ\nفهؤلاء هم الأعداء على الحقيقة؛ فلا تطعهم في بعض الأمور التي تنقض التقوى وتناقضها. السعدي:٦٥٧.\nلماذا نهى الله عن طاعة الكافرين والمنافقين؟\nوَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ مِن رَّبِّكَۚ\nيعني: القرآن، وفيه زجر عن اتباع مراسم الجاهلية، وأمر بجهادهم ومنابذتهم، وفيه دليل على ترك اتباع الآراء مع وجود النص؛ والخطاب له ولأمته. القرطبي:١٧/٥١\nكيف ترد على من يترك القرآن، ويتبع هواه وأقوال البشر؟\nوَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ ٤\nالأدعياء: جمع دعيّ؛ وهو الذي يدعى ولد فلان وليس بولده. وسببها أمر زيد بن حارثة؛ وذلك أنه كان فتى من قبيلة كلب، فسباه بعض العرب وباعه من خديجة، فوهبته للنبي -صلى الله عليه وسلم- فتبناه، فكان يقال له: زيد بن محمد، حتى أنزلت هذه الآية. ابن جزي:٢/١٨٢.\nأبطلت هذه الآية عادة من عادات الجاهلية، فما هي؟\nٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ\n﴿مِّنۡ أَنفُسِهِمۡ﴾: فضلًا عن آبائهم في نفوذ حكمه فيهم، ووجوب طاعته عليهم؛ لأنه لا يدعوهم إلا إلى العقل والحكمة، ولا يأمرهم إلا بما ينجيهم، وأنفسهم إنَّما تدعوهم إلى الهوى والفتنة؛ فتأمرهم بما يرديهم. البقاعي:١٥/٢٩٠.\nلماذا كان النبي -صلى الله عليه وسلم- أولى بنا من أنفسنا؟\nوَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ\nشرف الله تعالى أزواج نبيه -صلى الله عليه وسلم- بأن جعلهن أمهات المؤمنين؛ أي: في وجوب التعظيم والمبرة والإجلال، وحرمة النكاح على الرجال. القرطبي:١٧/٦٢.\nكيف ترد على المبتدعة في انتقاصهم لأمهات المؤمنين من خلال الآية الكريمة؟"],[419,"§الأحزاب\nwords\nزَاغَتِ الأَبصَارُشَخَصَتِ الأَبصَارُ؛ حَيرَةً وَدَهشَةً.\nغُرُورًابَاطِلًا خَادِعًا.\nيَثرِبَهُوَ: الاِسمُ الجَاهِلِيُّ لِلمَدِينَةِ.\nلاَ مُقَامَ لَكُملاَ إِقَامَةَ لَكُم فِي مَعرَكَةٍ خَاسِرَةٍ.\nبُيُوتَنَا عَورَةٌغَيرُ مُحَصَّنَةٍ.\nأَقطَارِهَاجَوَانِبِ المَدِينَةِ.\ndeeds\nتأمل في سيرة أولي العزم من الرسل، واكتب أهم الصفات المشتركة بينهم.\nاقرأ عن غزوة الأحزاب لتعلم كيف حفظ الله لنا الدين بتثبيت النبي -صلى الله عليه وسلم- وأصحابه.\nاستعذ بالله من النفاق وأهله.\nguid\nغزوة الخندق من أشد الغزوات وأكثرها ألمًا وتعبًا على المسلمين.\nيبتلي الله عباده ليعلم الصادقين من الكاذبين.\nالمنافق لا عهد له ولا ميثاق مع الخالق، فكيف مع الخلق.\nrefl\nوَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا ٧\nإنَّما خص هؤلاء الخمسة -وإن دخلوا في زمرة النبيين- تفضيلًا لهم، وقيل: لأنهم أصحاب الشرائع والكتب، وأولو العزم من الرسل وأئمة الأمم. القرطبي:١٧/٦٨.\nلم خص هؤلاء الرسل بالذكر في هذا الموضع؟\nوَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا ٧ لِّيَسۡـَٔلَ ٱلصَّٰدِقِينَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَٰفِرِينَ عَذَابًا أَلِيمٗا ٨\nيخبر تعالى أنه أخذ من النبيين... ميثاقهم الغليظ، وعهدهم الثقيل المؤكد على القيام بدين الله والجهاد في سبيله... وسيسأل الله الأنبياء وأتباعهم عن هذا العهد الغليظ؛ هل وفوا فيه وصدقوا فيثيبهم جنات النعيم؟! أم كفروا فيعذبهم العذاب الأليم؟! السعدي:٦٥٩.\nهل السؤال عن الميثاق الغليظ خاص بالأنبياء والرسل؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ جُنُودٞ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا وَجُنُودٗا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ٩\nكانت هذه الريح معجزة للنبي -صلى الله عليه وسلم-؛ لأن النبي -صلى الله عليه وسلم- والمسلمين كانوا قريبًا منها، لم يكن بينهم وبينها إلا عرض الخندق، وكانوا في عافية منها، ولا خبر عندهم بها. القرطبي:١٦/٩٠.\nبيّن وجه الإعجاز بإرسال الريح في غزوة الأحزاب.\nوَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ\n﴿وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ﴾: مالت وشخصت من الرعب، وقيل: مالت عن كل شيء؛ فلم تنظر إلا إلى عدوها، ﴿وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ﴾: فزالت عن أماكنها حتى بلغت الحلوق من الفزع. البغوي:٣/٥٤٤.\nعلى ماذا تدل الأوصاف التي وقعت للمؤمنين في غزوة الأحزاب؟\nإِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠ ١٠\n﴿وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠﴾ أي: تظنون أن الكفار يغلبونكم، وقد وعدكم الله بالنصر عليهم. فأما المنافقون؛ فظنوا ظن السوء وصرحوا به، وأمَّا المؤمنون؛ فربما خطرت لبعضهم خطرة مما لا يمكن البشر دفعها، ثم استبصروا، ووثقوا بوعد الله. ابن جزي:٢/١٨٣.\nما الفرق بين ظن المؤمنين وظن المنافقين؟\nوَإِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورٗا ١٢\nظاهر العطف أنهم قوم لم يكونوا منافقين، فقيل: هم قوم كان المنافقون يستميلونهم بإدخال الشبهة عليهم، وقيل: قوم كانوا ضعفاء الاعتقاد لقرب عهدهم بالإسلام. الألوسي:١١/١٥٦.\nمن الفئة التي يختارها المنافقون لبث شبهاتهم؟\nوَإِذۡ قَالَت طَّآئِفَةٞ مِّنۡهُمۡ يَٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقٞ مِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةٞ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ إِلَّا فِرَارٗا ١٣\n﴿طَآئِفَةٌ مِّنۡهُمۡ﴾ أي: قوم كثير من موتى القلوب ومرضاها يطوف بعضهم ببعض. (يا أهل يثرب) عدلوا عن الاسم الذي وسمها به النبي -صلى الله عليه وسلم- من: المدينة وطَيْبَة -مع حسنه- إلى الاسم الذي كانت تُدعى به قديمًا -مع احتمال قبحه باشتقاقه من الثرب الذي هو اللوم والتعنيف- إظهارًا للعدول عن الإسلام. البقاعي:١٥/٣٠٦.\nلماذا عدلوا إلى الاسم القديم للمدينة عما سماها به النبي -عليه الصلاة والسلام-؟"],[420,"§الأحزاب\nwords\nالمُعَوِّقِينَالمُثَبِّطِينَ عَنِ الجِهَادِ.\nأَشِحَّةًبُخَلاَءَ بِأَموَالِهِم وَأَنفُسِهِم وَجُهُودِهِم.\nتَدُورُ أَعيُنُهُمخَوفًا، وَهَلَعًا.\nسَلَقُوكُمرَمَوكُم.\nحِدَادٍذَرِبَةٍ، سَلِيطَةٍ، مُؤذِيَةٍ.\nبَادُونَ فِي البَادِيَةِ.\ndeeds\nادع الله تعالى أن يعصِمك من مضلات الفتن ما ظهر منها وما بطن.\nسبّح الله تعالى اليوم وكبره، واحمده قدر ما تستطيع.\nطبق سنة من السنن المهجورة.\nguid\nالفرار من مواطن المحن والشدائد لا يزيد الأعمار، ولا يؤخر الآجال، بل ربَّما كان ذلك سببًا في تعجيل أخذه على غرة.\nمن صفات المنافقين: التخذيل، وتعطيل أعمال الخير؛ فاحذر أن تكون مغلاقًا للخير، مفتاحًا للشر.\nأكثر ما يعين على الاقتداء بالنبي -صلى الله عليه وسلم- تذكر الآخرة، وذكر الله -عز وجل-.\nrefl\nقُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ\nوالأسباب تنفع إذا لم يعارضها القضاء والقدر، فإذا جاء القضاء والقدر تلاشى كل سبب، وبطلت كل وسيلة ظنها الإنسان تنجيه. السعدي:٦٦٠.\nهل في الآية دليل على إبطال الأسباب؟\nقُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذٗا لَّا تُمَتَّعُونَ إِلَّا قَلِيلٗا ١٦\nوالمقصود من الآية: تخليق المسلمين بخُلق استضعاف الحياة الدنيا، وصرف هممهم إلى السعي نحو الكمال؛ الذي به السعادة الأبدية، سيرًا وراء تعاليم الدين. ابن عاشور:٢١/٢٩١.\nفي الآية تربية للمسلم في تقديم الآخرة الباقية على الدنيا الزائلة. وضح ذلك.\n۞قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا ١٨\nأي: الذين يعوِّقون الناس عن الجهاد، ويمنعونهم منه بأقوالهم وأفعالهم، ﴿وَٱلۡقَآئِلِينَ لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ﴾: هم المنافقون الذين قعدوا بالمدينة عن الجهاد، وكانوا يقولون لقرابتهم أو للمنافقين مثلهم: هلم إلى الجلوس معنا بالمدينة، وترك القتال. ابن جزي:٢/١٨٤.\nبيّن الله في هذه الآية وما بعدها واحدة من صفات المنافقين، اذكرها.\nأَشِحَّةً عَلَيۡكُمۡۖ أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ أُوْلَٰٓئِكَ لَمۡ يُؤۡمِنُواْ\n﴿أَشِحَّةً عَلَيۡكُمۡۖ﴾: بأبدانهم عند القتال، وأموالهم عند النفقة فيه؛ فلا يجاهدون بأموالهم وأنفسهم... ﴿أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ﴾: الذي يراد منهم؛ وهذا شر ما في الإنسان: أن يكون شحيحًا بما أُمر به، شحيحًا بماله أن ينفقه في وجهه، شحيحًا في بدنه أن يجاهد أعداء الله أو يدعو إلى سبيل الله، شحيحًا بجاهه، شحيحًا بعلمه ونصيحته ورأيه. السعدي:٦٦١.\nعدد أنواعًا من الشح المقصود في هذه الآية.\nفَإِذَا جَآءَ ٱلۡخَوۡفُ رَأَيۡتَهُمۡ يَنظُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ كَٱلَّذِي يُغۡشَىٰ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ\nلتصوير هيئة نظرهم نظر الخائف المذعور؛ الذي يحدّق بعينيه إلى جهات يحذر أن تأتيه المصائب من إحداها. ابن عاشور:٢١/٢٩٧.\nفي الآية الكريمة صفة للمنافقين تظهر عند حضور المخاوف، اذكرها.\nلَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا ٢١\nاستدل الأصوليون في هذه الآية على الاحتجاج بأفعال الرسول -صلى الله عليه وسلم-، وأن الأصل أن أمته أسوته في الأحكام، إلا ما دل الدليل الشرعي على الاختصاص به. السعدي:٦٦١.\nهل يُحتج بأفعال الرسول -صلى الله عليه وسلم-؟\nوَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنٗا وَتَسۡلِيمٗا ٢٢\nدليل على زيادة الإيمان وقوته بالنسبة إلى الناس وأحوالهم؛ كما قال جمهور الأئمة: إنه يزيد وينقص. ابن كثير:٣/٤٥٧.\nهل يزيد الإيمان وينقص؟ وضح ذلك من خلال هذه الآية."],[421,"§الأحزاب\nwords\nقَضَى نَحبَهُوَفَى بِنَذرِهِ فِي نُصرَةِ دِينِهِ، أَو مَاتَ شَهِيدًا.\nبِغَيظِهِم لَم يَنَالُوا خَيرًامُغتَاظِينَ لَم يَنَالُوا مَا أَرَادُوا.\nظَاهَرُوهُمعَاوَنُوا الأَحزَابَ.\nصَيَاصِيهِمحُصُونِهِم.\nوَأُسَرِّحكُنَّأُطَلِّقكُنَّ.\nبِفَاحِشَةٍ مُبَيِّنَةٍمَعصِيَةٍ ظَاهِرَةٍ.\ndeeds\nاستعرض بعض سير الصحابة؛ فهم قدوتنا.\nأرسل رسالة عن الثبات على دين الله وأهميته.\nسل الله تعالى أن يرزقك الصدق ويثبتك عليه حتى تلقاه.\nguid\nعِظَم منزلة الصحابة وفضلهم، وتزكية الله لهم؛ فمن سبّهم فقد كذَّب القرآن.\nقدرة الله لا تحد أبدًا؛ فهو تعالى على كل شيء قدير، لا يعجزه شيء.\nبيان أن سيئة العالم والشريف أشد من سيئة الجاهل والوضيع.\nrefl\nمِّنَ ٱلۡمُؤۡمِنِينَ رِجَالٞ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلٗا ٢٣\nفهؤلاء الرجال على الحقيقة، ومن عداهم؛ فصورهم صور رجال، وأمَّا الصفات فقد قصرت عن صفات الرجال. السعدي:٦٦١.\nما الرجولة الحقيقية؟\nوَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ٢٤\nوتعليق التعذيب على المشيئة تنبيه لهم بسَعَة رحمة الله، وأنه لا يقطع رجاءهم في السعي إلى مغفرة ما أتوه بأن يتُوبوا فيتوب الله عليهم. ابن عاشور:٢١/٣٠٩.\nلماذا علق التعذيب على المشيئة في الآية الكريمة؟\nوَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا ٢٤\n﴿أَوۡ يَتُوبَ عَلَيۡهِمۡ﴾: بأن يوفقهم للتوبة والإنابة. وهذا هو الغالب على كرم الكريم؛ ولهذا ختم الآية باسمين دالين على المغفرة، والفضل، والإحسان. السعدي:٦٦٢.\nلماذا ختم الآية باسميه (الغفور) و(الرحيم)؟\nوَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزٗا ٢٥\n﴿وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ﴾: بأن أرسل عليهم ريحًا وجنودًا حتى رجعوا، ورجعت بنو قريظة إلى صياصيهم؛ فكفى أمر قريظة بالرعب. القرطبي:١٦/١١٥.\nمن قوة الله وعزته أن له جنودًا لا يعلمها إلا هو، بين هذا من خلال الآية.\nوَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضٗا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا ٢٧\n(وأرضًا لم تطئوها): هذا وعد بفتح أرض لم يكن المسلمون قد وطئوها حينئذ، وهي مكة، واليمن، والشام، والعراق، ومصر؛ فأورث الله المسلمين جميع ذلك وما وراءها إلى أقصى المشرق والمغرب. ابن جزي:٢/١٨٦.\nبيّن وجه الإعجاز في قوله: (وأرضًا لم تطئوها).\nوَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمٗا ٢٩\nوفي هذا التخيير فوائد عديدة:... ومنها: إظهار رفعتهن، وعلو درجتهن، وبيان علو هممهن؛ أن كان الله ورسوله والدار الآخرة مرادهن ومقصودهن دون الدنيا وحطامها. السعدي:٦٦٣.\nفي هذا التخيير إظهار لترفع أمهات المؤمنين، فبَيِّن وجه ذلك.\nيَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةٖ مُّبَيِّنَةٖ يُضَٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا ٣٠\nكلما تضاعفت الحرمات فهتكت تضاعفت العقوبات؛ ولذلك ضوعف حد الحر على العبد، والثيب على البكر. القرطبي:١٦/١٣٣.\nهل من علت رتبته تضاعف الخطأ في حقه؟"],[422,"§الأحزاب\nwords\nيَقنُت مِنكُنَّتُطِع مِنكُنَّ اللهَ وَرَسُولَهُ.\nوَأَعتَدنَاأَعدَدنَا.\nوَقَرنَالزَمنَ.\nالرِّجسَالأَذَى، وَالسُّوءَ، وَالإِثمَ.\nوَالقَانِتِينَالمُطِيعِينَ، الخَاضِعِينَ للهِ.\nوَالخَاشِعِينَالخَائِفِينَ مِنَ اللهِ، المُتَوَاضِعِينَ.\ndeeds\nذكر أخواتك بعدم الخضوع بالقول عند الحاجة لمخاطبة الرجال غير المحارم، أو الرد على الهاتف.\nأرسل رسالة عن أهمية قرار المرأة في بيتها، وخاصة في هذا الزمن.\nاحرص أن يكون لك في بيتك ورد دائم من كتاب الله، وأحاديث من سنة رسول الله -صلى الله عليه وسلم-.\nguid\nخطورة خضوع النساء في القول.\nحرمة التبرج، وأنه من علامات الجاهلية.\nقراءة القرآن والأدعية المأثورة في البيوت تحصنها ومن فيها من شياطين الأنس والجن.\nrefl\n۞وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحٗا نُّؤۡتِهَآ أَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقٗا كَرِيمٗا ٣١\nفي إضافة الأجر إلى ضميرها إشارة إلى تعظيم ذلك الأجر بأنه يناسب مقامها، وإلى تشريفها بأنها مستحقة ذلك الأجر. ومضاعفة الأجر لهن على الطاعات كرامة لقدرهنّ. ابن عاشور:٢٢/٥.\nبيّن منزلة أزواج النبي -صلى الله عليه وسلم- من خلال الآية الكريمة.\nيَٰنِسَآءَ ٱلنَّبِيِّ لَسۡتُنَّ كَأَحَدٖ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ\nفضلهن الله على النساء بشرط التقوى، وقد حصل لهن التقوى فحصل التفضيل على جميع النساء؛ إلا أنه يخرج من هذا العموم: فاطمة بنت رسول الله -صلى الله عليه وسلم-، ومريم بنت عمران، وآسية امرأة فرعون؛ لشهادة رسول الله -صلى الله عليه وسلم- لكل واحدة منهن بأنها سيدة نساء عالمها. ابن جزي: ٢/١٨٨.\nما شرط تفضيل أمهات المؤمنين على سائر النساء؟ ومن غيرهن حصلن على هذا التفضيل؟\nفَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضٞ وَقُلۡنَ قَوۡلٗا مَّعۡرُوفٗا ٣٢\nفإن القلب الصحيح ليس فيه شهوة لما حرم الله؛ فإن ذلك لا تكاد تميله ولا تحركه الأسباب لصحة قلبه وسلامته من المرض. بخلاف مريض القلب، الذي لا يتحمل ما يتحمل الصحيح، ولا يصبر على ما يصبر عليه؛ فأدنى سبب يوجد يدعوه إلى الحرام يجيب دعوته ولا يتعاصى عليه. السعدي:٦٦٤.\nلماذا خص القلب المريض بالذكر؟\nوَقُلۡنَ قَوۡلٗا مَّعۡرُوفٗا ٣٢\nلما نهاهن عن الخضوع في القول فربما تُوهِّم أنهن مأمورات بإغلاظ القول، دفع هذا بقوله: ﴿وَقُلۡنَ قَوۡلًا مَّعۡرُوفًا﴾ أي: غير غليظ ولا جاف، كما أنه ليس بليِّن خاضع. السعدي:٦٦٤.\nلماذا ختم الآية بهذه الجملة ﴿وَقُلۡنَ قَوۡلًا مَّعۡرُوفًا﴾ ؟\nوَقَرۡنَ فِي بُيُوتِكُنَّ\nقيل لسودة -رضي الله عنها-: لم لا تخرجين؟ فقالت: أمرنا الله بأن نقرّ في بيوتنا. وكانت عائشة إذا قرأت هذه الآية تبكي على خروجها أيام الجمل. ابن جزي: ٢/١٨٨\nكيف امتثلت أمهات المؤمنين لهذه الآية؟\nإِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ\nوهذا نص في دخول أزواج النبي -صلى الله عليه وسلم- في أهل البيت هاهنا؛ لأنهن سبب نزول هذه الآية، وسبب النزول داخل فيه قولًا واحدًا. ابن كثير:٣/٤٦٥.\nكيف تبطل الآية الكريمة رأي الشيعة في آل البيت؟\nوَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ\nلما كان الصوم من أكبر العون على كسر الشهوة... ناسب أن يذكر بعده ﴿وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ﴾. ابن كثير:٣/٤٦٩.\nلماذا ذكر حفظ الفروج بعد الصيام؟"],[423,"§الأحزاب\nwords\nقَضَىحَكَمَ.\nقَضَى زَيدٌ مِنهَا وَطَرًاطَلَّقَهَا.\nأَدعِيَائِهِممَن كَانُوا يَتَبَنَّونَهُم.\nوَطَرًاحَاجَةً.\nحَرَجٍإِثمٍ.\ndeeds\nاذكر الله هذا اليوم أكثر من ذكرك له بالأمس.\nصلِّ على النبي -صلى الله عليه وسلم- في الصباح والمساء حتى يصلي الله عليك.\nاحضر درسًا علميًا أو محاضرة لتصلي عليك الملائكة.\nguid\nالحذر من تأويل الأوامر الصريحة حسب ما تهواه النفس، ووجوب التسليم والانقياد لأوامر الشرع؛ فإنها من لوازم الإيمان بالله وبالرسول.\nاعلم أنه لا أحد أعلى من النصيحة والموعظة والتذكير.\nدفاع الله تعالى عن أوليائه والمبلّغين عنه.\nrefl\nوَمَا كَانَ لِمُؤۡمِنٖ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ\nمعناها: أنه ليس لمؤمن ولا مؤمنة اختيار مع الله ورسوله، بل يجب عليهم التسليم والانقياد لأمر الله ورسوله. ابن جزي:٢/١٨٩.\nما الواجب على المؤمن إذا بلغه الدليل من الكتاب والسنة؟\nوَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ\nمن الرأي الحسن لمن استشار في فراق زوجته: أن يؤمر بإمساكها مهما أمكن صلاح الحال، فهو أحسن من الفُرقة. السعدي:٦٦٦.\nما الذي ينبغي أن يُشار به على من أراد ترك زوجته؟\nوَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ\nالرسول -صلى الله عليه وسلم- قد بلغ البلاغ المبين؛ فلم يدع شيئًا مما أوحي إليه إلا وبلغه، حتى هذا الأمر الذي فيه عتابه. السعدي:٦٦٦.\nبَلَغَ النبي -صلى الله عليه وسلم- غاية الصدق في تبليغ ما أوحي إليه، كيف تستشهد على ذلك من هذه الآية؟\nفَلَمَّا قَضَىٰ زَيۡدٞ مِّنۡهَا وَطَرٗا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجٞ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرٗاۚ\nالتعليم الفعلي أبلغ من القولي، خصوصًا إذا اقترن بالقول؛ فإن ذلك نور على نور. السعدي:٦٦٦.\nفي الآية إشارة إلى التربية بالتطبيق العملي، وضحه.\nمَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٖ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا ٤٠\nواستدراك قوله: ﴿وَلَٰكِن رَّسُولَ ٱللَّهِ﴾ لرفع ما قد يُتوهم مِن نفي أبوته من انفصال صلة التراحم والبرِّ بينه وبين الأمة؛ فذُكِّروا بأنه رسول الله -صلى الله عليه وسلم- فهو كالأب لجميع أمته في شفقته ورحمته بهم، وفي برّهم وتوقيرهم إياه؛ شأن كل نبي مع أمته. ابن عاشور:٢٢/٤٤.\nما فائدة الاستدراك الوارد في قوله تعالى: ﴿وَلَٰكِن رَّسُولَ ٱللَّهِ﴾؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ٤١\nاشترط الله الكثرة في الذكر حيثما أمر به بخلاف سائر الأعمال. والذكر يكون بالقلب وباللسان، وهو على أنواع كثيرة من: التهليل، والتسبيح، والحمد، والتكبير، وذكر أسماء الله تعالى. ابن جزي:٢/١٩١.\nمن خلال هذه الآية، بم اختص الذكر على سائر الأعمال الفاضلة؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ٤١\nأمر الله تعالى عباده بأن يذكروه ويشكروه، ويكثروا من ذلك على ما أنعم به عليهم، وجعل تعالى ذلك دون حد لسهولته على العبد، ولعظم الأجر فيه. قال ابن عباس: \"لم يعذر أحد في ترك ذكر الله إلا من غلب على عقله\". القرطبي:١٦/١٦٧.\nهل لأحد عذر في ترك ذكر الله تعالى؟"],[424,"§الأحزاب\nwords\nتَمَسُّوهُنَّتَدخُلُوا بِهِنَّ، وَتُجَامِعُوهُنَّ.\nعِدَّةٍمُدَّةٍ تَنتَظِرُ فِيهَا المَرأَةُ.\nتَعتَدُّونَهَاتُحصُونَهَا عَلَيهِنَّ.\nوَسَرِّحُوهُنّَ طَلِّقُوهُنَّ.\nأَفَاءَ الله عَلَيكَأَنعَمَ بِهِ عَلَيكَ بِالجِهَادِ.\nخَالِصَةً لَكَخَاصَّةً بِكَ.\ndeeds\nألق السلام بتواضع على من هو دونك في السن أو المنزلة، عسى أن يكون سببًا في سلام الله عليك يوم القيامة.\nسَلِ الله أن يرزقك الإخلاص، وأن يجنبك الرياء في دعوتك وأمرك بالمعروف ونهيك عن المنكر.\nبشّر إخوةً لك بما أعده الله لهم من الفضل العظيم لصبرهم على عبادة الله وعلى أقدار الله.\nguid\nعِظَم مكانة النبي -صلى الله عليه وسلم- ومنزلته وفضله على سائر الخلق.\nمشروعية الدعوة إلى الله إذا كان الداعي متأهلًا بالعلم والحلم.\nحرمة طاعة الكافرين والمنافقين والفجرة والظالمين فيما يتنافى مع مرضاة الله تعالى.\nrefl\nيَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا ٤٥ وَدَاعِيًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجٗا مُّنِيرٗا ٤٦\nهذه الأشياء التي وصف الله بها رسوله محمدًا -صلى الله عليه وسلم- هي المقصود من رسالته، وزبدتها، وأصولها التي اختص بها. السعدي:٦٦٧.\nلماذا ذكرت هذه الأشياء الخمسة في وصف نبينا دون غيرها؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا ٤٥\nوقدمت البِشارة على النِذارة لأن النبي -صلى الله عليه وسلم- غلب عليه التبشير؛ لأنه رحمة للعالمين، ولكثرة عدد المؤمنين في أمته. ابن عاشور:٢٢/٥٣.\nلماذا قدمت البشارة على النذارة في وصفه -صلى الله عليه وسلم- في الآية؟\nوَدَاعِيًا إِلَى ٱللَّهِ\nإخلاص الدعوة إلى الله، لا إلى نفسه وتعظيمها، كما قد يعرض ذلك لكثير من النفوس في هذا المقام. السعدي:٦٦٨.\nقد يحصل زلل من الدعاة في شأن الإخلاص، وضِّح ذلك من خلال الآية؟\nوَبَشِّرِ ٱلۡمُؤۡمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلٗا كَبِيرٗا ٤٧\nقال ابن عطية: \"قال لنا أبي: هذه من أرجى آية عندي في كتاب الله تعالى؛ لأن الله -عز وجل- قد أمر نبيه أن يبشر المؤمنين بأن لهم عنده فضلًا كبيرًا، وقد بين تعالى الفضل الكبير في قوله تعالى: ﴿وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ﴾ [الشورى: ٢٢]\". القرطبي:١٦/١٧٣.\nبيّن كيف عد بعض العلماء هذه الآية من أرجى الآيات؟\nوَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ وَدَعۡ أَذَىٰهُمۡ\nفإن ذلك جالب لهم، وداع إلى قبول الإسلام، وإلى كفِّ كثير من أذيتهم له ولأهله. السعدي:٦٦٨.\nلماذا نهى الله عن أذية الكافرين والمنافقين؟\nوَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ وَدَعۡ أَذَىٰهُمۡ\nأي: لا تطعهم فيما يشيرون عليك من المداهنة في الدين ولا تمالئهم. القرطبي:١٦/١٧٣.\nيريد الكافرون والمنافقون من الداعية أمرًا معينًا، فما هو؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةٖ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحٗا جَمِيلٗا ٤٩\nوأمرهم بتمتيعهن بهذه الحالة بشيء من متاع الدنيا الذي يكون فيه جبر لخواطرهن لأجل فراقهن. السعدي:٦٦٨.\nما الحكمة من تشريع التمتيع هنا؟"],[425,"§الأحزاب\nwords\nتُرجِيتُؤَخِّرُ القَسمَ فِي المَبِيتِ، عَمَّن شِئتَ مِن زَوجَاتِكَ.\nوَتُؤوِيتَضُمُّ فِي المَبِيتِ.\nابتَغَيتَطَلَبتَ المَبِيتَ عِندَهَا.\nعَزَلتَأَخَّرتَ قِسمَهَا.\nنَاظِرِينَ إِنَاهُمُنتَظِرِينَ نُضجَهُ.\nمَتَاعًاشيئًا مِن أَوَانِي البَيتِ، وَنَحوِهَا.\ndeeds\nألق كلمة أو أرسل رسالة عن خطورة التساهل في الاختلاط بين الرجال والنساء.\nسَلِ الله أن يرزقك الجرأة، والحكمة، وحسن الأدب في قول الحق.\nذكّر زميلًا لك أن من الأدب مع العلماء والدعاة عدم الإطالة في الجلوس عند زيارتهم؛ لكثرة انشغالهم.\nguid\nتذكر أن الله تعالى يعلم ما في قلبك، فلا تودعن فيه إلا ما يرضيه سبحانه.\nدرّب نفسك على عدم الحياء من قول الحق والدعوة إليه.\nاحذر الاختلاط بالنساء غير المحارم؛ فكل وسيلة تبعد الرجال عن النساء، فهي طهارة لقلوب الطرفين.\nrefl\nوَكَانَ ٱللَّهُ عَلِيمًا حَلِيمٗا ٥١\nمناسبة صفة العلم لقوله: ﴿وَٱللَّهُ يَعۡلَمُ مَا فِي قُلُوبِكُمۡۚ﴾ ظاهرة. ومناسبة صفة الحليم باعتبار أن المقصود ترغيب الرسول -صلى الله عليه وسلم- في أليق الأحوال بصفة الحليم. ابن عاشور:٢٢/٧٧.\nما الحكمة من ختم الآية الكريمة بصفة الحلم؟\nلَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعۡدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَٰجٖ وَلَوۡ أَعۡجَبَكَ حُسۡنُهُنَّ\nهذا شكر من الله -الذي لم يزل شكورًا- لزوجات رسوله -رضي الله عنهن-؛ حيث اخترن الله ورسوله والدار الآخرة؛ أن رحمهن وقصر رسوله عليهن. السعدي:٦٧٠.\nفي الآية حثٌّ على تقديم الآخرة على الدنيا، فما وجه ذلك؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ\nقال ابن عباس: \"نزلت في قوم كانوا يتحينون طعام النبي -صلى الله عليه وسلم- فيدخلون عليه قبل الطعام، فيقعدون إلى أن يُطبخ، ثم يأكلون ولا يخرجون؛ فأمروا أن لا يدخلوا حتى يؤذن لهم، وأن ينصرفوا إذا أكلوا \". ﴿فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ﴾ أي: انصرفوا، قال بعضهم: هذا أدب أدّب الله به الثقلاء. ابن جزي:٢/١٩٤.\nما آداب الزيارة التي تستفاد من هذه الآية؟\nإِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ\nفالأمر الشرعي ولو كان يتوهم أن في تركه أدبًا وحياءً، فإن الحزم كل الحزم اتباع الأمر الشرعي، وأن يجزم أن ما خالفه ليس من الأدب في شيء. السعدي:٦٧٠.\nهل مطالبة الناس بحقوقهم التي أحقها لهم الشرع يعتبر مخالفًا للآداب والأذواق العامة؟\nوَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ\n﴿أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ﴾ أي: أكثر تطهيرًا من الخواطر الشيطانية التي تخطر للرجال في أمر النساء وللنساء في أمر الرجال؛ فإن الرؤية سبب التعلق والفتنة. وفي بعض الآثار: \"النظر سهم مسموم من سهام إبليس\". الألوسي:١١/٢٤٨.\nما أثر نظر الرجل والمرأة إلى غير محارمهم؟\nوَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ\nلأنه أبعد عن الريبة، وكلّما بعد الإنسان عن الأسباب الداعية إلى الشر فإنه أسلم له، وأطهر لقلبه؛ فلهذا من الأمور الشرعية التي بيَّن الله كثيرًا من تفاصيلها أن جميع وسائل الشر وأسبابه ومقدماته ممنوعة، وأنه مشروع البعد عنها بكل طريق. السعدي:٦٧٠\nمن حكمة الشرع أنه لم يكتف بتحريم الحرام فقط، بل حرم أسبابه والطرق الموصلة إليه؛ بيّن هذا باختصار من خلال الآية.\nذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ\nقلوب الفريقين طاهرة بالتقوى، وتعظيم حرمات الله وحرمة النبي -صلى الله عليه وسلم-، ولكن لمَّا كانت التقوى لا تصل بهم إلى درجة العصمة أراد الله أن يزيدهم منها بما يكسب المؤمنين مراتب من الحفظ الإِلهي من الخواطر الشيطانية؛ بقطع أضعف أسبابها، وما يقرب أمهات المؤمنين من مرتبة العصمة الثابتة لزوجهن -صلى الله عليه وسلم-؛ فإن الطيبات للطيبين بقطع الخواطر الشيطانية عنهن بقطع دابرها ولو بالفرض. ابن عاشور:٢٢/٩١.\nما السبيل الأمثل لطهارة القلوب؟"],[426,"§الأحزاب\nwords\nاحتَمَلُواارتَكَبُوا.\nبُهتَانًاأَفحَشَ الكَذِبِ وَالزُّورِ.\nيُدنِينَ عَلَيهِنّَ يُرخِينَ عَلَى رُؤُوسِهِنَّ وَوُجُوهِهِنَّ وَصُدُورِهِنَّ.\nوَالمُرجِفُونَالَّذِينَ يَنشُرُونَ الأَخبَارَ الكَاذِبَةَ.\nلَنُغرِيَنَّكَ بِهِملَنُسَلِّطَنَّكَ عَلَيهِم.\ndeeds\nصلِّ على النبي -صلى الله عليه وسلم- عدة مرات.\nاستغفر للمؤمنين والمؤمنات، خاصةً من نالهم أذى منك بلسانك أو بأفعالك؛ فإن الإنسان لا يخلو من الخطأ.\nاكتب رسالة عن فوائد حجاب المرأة ووجوبه.\nguid\nمن صفات الحجاب الشرعي أنه يخفي معالم المتحجبة حتى لا تعرف من هي.\nتذكر أن عاقبة أهل النفاق إلى بوار وبعد.\nسنن الله تعالى ثابتة لا تتبدل ولا تتغير.\nrefl\nلَّا جُنَاحَ عَلَيۡهِنَّ فِيٓ ءَابَآئِهِنَّ وَلَآ أَبۡنَآئِهِنَّ وَلَآ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتۡ أَيۡمَٰنُهُنَّۗ وَٱتَّقِينَ ٱللَّهَۚ\nخص النساء بالذكر، وعينهن في هذا الأمر؛ لقلة تحفظهن، وكثرة استرسالهن، والله أعلم. القرطبي:١٨/٢١٣.\nما الحكمة من تخصيص النساء بالأمر بالتقوى في آخر الآية؟\nإِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّۚ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ صَلُّواْ عَلَيۡهِ وَسَلِّمُواْ تَسۡلِيمًا ٥٦\nأخبر عباده بمنزلة عبده ونبيه عنده في الملأ الأعلى؛ بأنه يثني عليه عند الملائكة المقربين، وأن الملائكة تصلي عليه، ثم أمر تعالى أهل العالم السفلي بالصلاة والتسليم عليه؛ ليجتمع الثناء عليه من أهل العالمين: العلوي والسفلي جميعًا. ابن كثير:٣/٤٨٧.\nلماذا أمر الله بالصلاة والسلام على النبي -صلى الله عليه وسلم- بعد الإخبار بأن الله وملائكته يصلون عليه؟\nإِنَّ ٱلَّذِينَ يُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابٗا مُّهِينٗا ٥٧\nليس معنى إذايته أنه يضره الأذى؛ لأنه تعالى لا يضره شيء ولا ينفعه شيء، وقيل: إنها على حذف مضاف تقديره: يؤذون أولياء الله، والأوّل أرجح؛ لأنه ورد في الحديث يقول الله تعالى: «يشتمني ابن آدم وليس له أن يشتمني، ويكذبني وليس له أن يكذبني؛ أما شتمه إياي فقوله: إن لي صاحبة وولدًا، وأمَّا تكذيبه إياي فقوله: لا يعيدني كما بدأني». ابن جزي:٢/١٩٦.\nبيّن كيف يكون إيذاء الله تعالى.\nوَٱلَّذِينَ يُؤۡذُونَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ بِغَيۡرِ مَا ٱكۡتَسَبُواْ فَقَدِ ٱحۡتَمَلُواْ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا ٥٨\nألحقت حُرمة المؤمنين بحرمة الرسول -صلى الله عليه وسلم- تنويهًا بشأنهم، وذكروا على حدة للإِشارة إلى نزول رتبتهم عن رتبة الرسول -صلى الله عليه وسلم-. وهذا من الاستطراد معترض بين أحكام حُرمة النبي -صلى الله عليه وسلم- وآداب أزواجه وبناته والمؤمنات. ابن عاشور:٢٢/١٠٥.\nلماذا ذكرت حرمة المؤمنين بعد ذكر حرمة الرسول -صلى الله عليه وسلم-؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلۡمُؤۡمِنِينَ يُدۡنِينَ عَلَيۡهِنَّ مِن جَلَٰبِيبِهِنَّۚ\nأمر الله نبيه أن يأمر النساء عمومًا، ويبدأ بزوجاته وبناته... لأن الآمر لغيره ينبغي أن يبدأ بأهله قبل غيرهم؛ كما قال تعالى: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا﴾ [التحريم:٦]. السعدي:٦٧٢.\nما الفائدة الدعوية التي يفيدها الداعية وطالب العلم من هذه الآية؟\n۞لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ لَنُغۡرِيَنَّكَ بِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلٗا ٦٠\nلم يذكر المعمول الذي ينتهون عنه ليعم ذلك كل ما توحي به أنفسهم إليهم، وتوسوس به وتدعو إليه من الشرّ؛ من التعريض بسب الإسلام وأهله، والإرجاف بالمسلمين، وتوهين قواهم، والتعرض للمؤمنات بالسوء والفاحشة، وغير ذلك من المعاصي الصادرة من أمثال هؤلاء. السعدي:٦٧٢.\nلماذا لم يُذكر معمول الإرجاف الذي يقع من المرجفين؟\n۞لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ لَنُغۡرِيَنَّكَ بِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلٗا ٦٠\nوهذا فيه دليل لنفي أهل الشر الذين يتضرر بإقامتهم بين أظهر المسلمين؛ فإن ذلك أحسم للشر، وأبعد منه. السعدي:٦٧٢.\nفي الآية توجيه بالابتعاد عن أهل الشر وإبعادهم، بيِّن ذلك."],[427,"§الأحزاب\nwords\nسَعِيرًانَارًا مُوقَدَةً، شَدِيدَةَ الحَرَارَةِ.\nضِعفَينِمِثلَينِ.\nوَجِيهًاعَظِيمَ القَدرِ.\nسَدِيدًامُوَافِقًا لِلحَقِّ، خَالِيًا مِنَ الكَذِبِ وَالبَاطِلِ.\nفَأَبَينَامتَنَعنَ.\nوَأَشفَقنَخِفنَ مِنَ الخِيَانَةِ فِيهَا.\ndeeds\nقل: \"اللهم اصرف عني عذاب جهنم؛ إن عذابها كان غرامًا\".\nدافع بكتابة رسالةٍ أو مقالٍ، أو بإلقاء كلمة عن رجلٍ صالح اتهم زورًا وبهتانًا.\nقل: \"اللهم سدد لساني، واهد قلبي\".\nguid\nلا تتبع سيدًا ولا كبيرًا في معصية الله؛ فإنهم لن يغنوا عنك من الله شيئًا.\nأحسن إلى عباد الله، ولا تؤذ مسلمًا؛ خصوصًا العلماء والمصلحين.\nتذكر عظيم الأمانة التي تحملها ابن آدم.\nrefl\nوَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا ٦٣ إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَٰفِرِينَ وَأَعَدَّ لَهُمۡ سَعِيرًا ٦٤\nومجرد مجيء الساعة قربًا وبعدًا ليس تحته نتيجة ولا فائدة، وإنَّما النتيجة والخسار والربح والشقاء والسعادة: هل يستحق العبد العذاب، أو يستحق الثواب؟! فهذه سأخبركم بها، وأصف لكم مستحقها، فوصف مستحق العذاب، ووصف العذاب؛ لأن الوصف المذكور منطبق على هؤلاء المكذبين بالساعة؛ فقال: ﴿إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَٰفِرِينَ﴾. السعدي:٦٧٢.\nما الحكمة من ذكر عذاب الكافرين بعد ذكر قرب الساعة؟\nيَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِي ٱلنَّارِ يَقُولُونَ يَٰلَيۡتَنَآ أَطَعۡنَا ٱللَّهَ وَأَطَعۡنَا ٱلرَّسُولَا۠ ٦٦\nوتخصيص الوجوه بالذكر من بين سائر الأعضاء؛ لأن حر النار يؤذي الوجوه أشد مما يؤذي بقية الجلد؛ لأن الوجوه مقرّ الحواس الرقيقة: العيون، والأفواه، والآذان، والمنافس؛ كقوله تعالى: ﴿أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِ﴾ [الزمر:٢٤]. ابن عاشور:٢٢/١١٦.\nلماذا خصت الوجوه بالذكر من بين سائر الأعضاء في الآية الكريمة؟\nفَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُواْۚ وَكَانَ عِندَ ٱللَّهِ وَجِيهٗا ٦٩\nقال ابن عباس: \"كان حظيًا عند الله لا يسأل شيئًا إلا أعطاه\"، وقال الحسن: \"كان مستجاب الدعوة\"، وقيل: كان محببًا مقبولًا. البغوي:٣/٥٨٨.\nبيّن منزلة موسى -عليه السلام- عند ربه تعالى.\nوَقُولُواْ قَوۡلٗا سَدِيدٗا ٧٠ يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِيمًا ٧١\n﴿وَقُولُواْ قَوۡلًا سَدِيدًا﴾: قال ابن عباس: صوابًا، وقال قتادة: عدلًا، وقال الحسن: صدقًا... ﴿يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ﴾: قال ابن عباس: يتقبل حسناتكم، وقال مقاتل: يُزَكِّ أعمالكم. (ويغفرلكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزًا عظيمًا): أي: ظفر بالخير كله. البغوي:٣/٥٨٩.\nما العواقب الحسنة لحفظ اللسان وتحري القول السديد؟\nإِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا ٧٢\nالأمانة هي التكاليف الشرعية من: التزام الطاعات وترك المعاصي، وقيل: هي الأمانة في الأموال، وقيل: غسل الجنابة؛ والصحيح العموم في التكاليف. ابن جزي:٢/١٩٨.\nما الأمانة التي حمّلنا الله إياها؟\nإِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا ٧٢\nوعطف الجبال على الأرض وهي منها؛ لأن الجبال أعظم الأجزاء المعروفة من ظاهر الأرض، وهي التي تشاهد الأبصارُ عظمتها. ابن عاشور:٢٢/١٢٥.\nلماذا عطف الجبال على الأرض وهي منها؟\nإِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومٗا جَهُولٗا ٧٢ لِّيُعَذِّبَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمَۢا ٧٣\nيعظم تعالى شأن الأمانة التي ائتمن الله عليها المكلفين... فانقسم الناس بحسب قيامهم بها وعدمه إلى ثلاثة أقسام: منافقون أظهروا أنهم قاموا بها ظاهرًا لا باطنًا، ومشركون تركوها ظاهرًا وباطنًا، ومؤمنون قائمون بها ظاهرًا وباطنًا؛ فذكر الله تعالى أعمال هذه الأقسام الثلاثة، وما لهم من الثواب والعقاب، فقال: ﴿لِّيُعَذِّبَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمَۢا﴾. السعدي:٦٧٤.\nما أقسام الناس تجاه الأمانة؟"]])